    /// mean rediscovering which roles actually touch a remote when that work starts.
    #[test]
    fn the_designer_is_still_the_one_role_whose_own_work_needs_no_remote() {
        assert!(!Role::Designer.work_reaches_a_remote());
        for r in ALL_ROLES {
            if r == Role::Designer {
