import { describe, it, expect } from "vitest";
import { parseFeaturesFile, featuresToPlanIssues, requiredId } from "@/features/planner/issues/featureList";

describe("parseFeaturesFile", () => {
  it("returns [] for empty / bad JSON / non-array", () => {
    expect(parseFeaturesFile("")).toEqual([]);
    expect(parseFeaturesFile("   ")).toEqual([]);
    expect(parseFeaturesFile("{not json")).toEqual([]);
    expect(parseFeaturesFile('{"slug":"x","name":"X"}')).toEqual([]); // object, not array
  });

  it("parses a clean feature array", () => {
    const f = parseFeaturesFile(JSON.stringify([
      { slug: "invite", name: "Invite teammates", behavior: "send an invite", acceptance: ["email sent"], tools: ["resend"] },
    ]));
    expect(f).toHaveLength(1);
    expect(f[0]).toMatchObject({ slug: "invite", name: "Invite teammates", behavior: "send an invite" });
    expect(f[0].acceptance).toEqual(["email sent"]);
    expect(f[0].tools).toEqual(["resend"]);
    expect(f[0].stream).toBe("invite"); // defaults to slug
  });

  it("parses dependsOn (#plan-db)", () => {
    const f = parseFeaturesFile(JSON.stringify([
      { slug: "kernel", name: "Kernel" },
      { slug: "sketcher", name: "Sketcher", dependsOn: ["kernel"] },
    ]));
    expect(f[1].dependsOn).toEqual(["kernel"]);
  });

  // #4080 — the plan → algorithms-graph edge. Both spellings, because the store emits camelCase but a
  // hand-written or older payload may carry snake, and silently dropping it loses the reference outright.
  it("parses requires, tolerating both spellings (#4080)", () => {
    const f = parseFeaturesFile(JSON.stringify([
      { slug: "sorter", name: "Sorter", requires: ["merge.rs", "binary-search.ts"] },
      { slug: "snake", name: "Snake", requires_: ["merge.rs"] },
      { slug: "none", name: "None" },
    ]));
    expect(f[0].requires).toEqual(["merge.rs", "binary-search.ts"]);
    expect(f[1].requires).toEqual(["merge.rs"]);
    // Absent ⇒ `undefined`, the same convention every other array field here follows (`strArray`
    // collapses absent AND empty to undefined). Deliberately NOT normalized to `[]` for this one field
    // — a lone exception would be worse than the convention.
    expect(f[2].requires).toBeUndefined();
  });

  // REGRESSION (`the-feature-rules-live-in-typescript-not-the-crate`). `requires` was typed `string[]`
  // and coerced with `strArray`, which filters to strings — so every ATTRIBUTED entry Rust writes
  // ({id,by,at,note}, the `RequiredRef::Entry` arm) was silently dropped and the Features board showed
  // an empty `requires` for a feature that declared three. Against the old code the first two of these
  // fail: the entry vanishes and the list collapses to the bare id alone.
  it("keeps an ATTRIBUTED requires entry whole, alongside bare ids", () => {
    const f = parseFeaturesFile(JSON.stringify([{
      slug: "glance", name: "Glance",
      requires: [
        "safe-invoke.ts",
        { id: "use-poll.ts", by: "director", at: "2026-09-03T18:00:00Z", note: "the poll" },
        { id: "bsc.ts", by: "worker" },
      ],
    }]));
    expect(f[0].requires).toHaveLength(3);
    expect(f[0].requires?.[0]).toBe("safe-invoke.ts");
    expect(f[0].requires?.[1]).toEqual({ id: "use-poll.ts", by: "director", at: "2026-09-03T18:00:00Z", note: "the poll" });
    expect(f[0].requires?.[2]).toEqual({ id: "bsc.ts", by: "worker" });
    // The id is reachable whichever arm an entry takes — what every reader actually wants.
    expect(f[0].requires?.map(requiredId)).toEqual(["safe-invoke.ts", "use-poll.ts", "bsc.ts"]);
  });

  it("drops a malformed requires entry rather than admitting a shapeless object", () => {
    const f = parseFeaturesFile(JSON.stringify([{
      slug: "a", name: "A", requires: [{ by: "nobody" }, { id: "   " }, 42, "ok.ts"],
    }]));
    expect(f[0].requires).toEqual(["ok.ts"]);
  });

  it("derives a slug from the name when missing, and an explicit stream wins", () => {
    const f = parseFeaturesFile(JSON.stringify([{ name: "Export to CSV", stream: "exporter" }]));
    expect(f[0].slug).toBe("export-to-csv");
    expect(f[0].stream).toBe("exporter");
  });

  it("drops entries with no name and de-dupes slugs", () => {
    const f = parseFeaturesFile(JSON.stringify([
      { slug: "a", name: "A" },
      { slug: "a", name: "A duplicate" },
      { behavior: "no name" },
    ]));
    expect(f.map((x) => x.slug)).toEqual(["a"]);
  });

  it("ignores malformed field types", () => {
    const f = parseFeaturesFile(JSON.stringify([{ slug: "a", name: "A", acceptance: "not-an-array", tools: [1, "ok", ""] }]));
    expect(f[0].acceptance).toBeUndefined();
    expect(f[0].tools).toEqual(["ok"]);
  });
});

describe("featuresToPlanIssues (#plan-db — publish generates issues from features)", () => {
  it("maps one issue per feature: slug→ref, acceptance/dependsOn carry over, prose→body", () => {
    const issues = featuresToPlanIssues([
      { slug: "kernel", name: "Geometry kernel", behavior: "evaluate solids", acceptance: ["booleans work"], approach: "BREP", tools: ["opencascade"], dependsOn: [] },
      { slug: "sketcher", name: "Sketcher", dependsOn: ["kernel"] },
    ]);
    expect(issues[0]).toMatchObject({ ref: "kernel", title: "Geometry kernel", acceptance: ["booleans work"], stream: "kernel" });
    expect(issues[0].body).toContain("evaluate solids");
    expect(issues[0].body).toContain("## Approach");
    expect(issues[1]).toMatchObject({ ref: "sketcher", dependsOn: ["kernel"] }); // feature edge → issue dep
  });
});

implementations.code:
// The COMMAND-SURFACE node projection (`epic-command-surfaces-are-nodes`, slice 1) — turn the crate
// roster into Glance nodes and edges.
//
// The roster comes from `bsc surface crates --json`: every workspace member, whether it exposes verbs,
// the verbs it serves (joined from the one catalog), and its internal cargo dependencies. This module
// is the PURE projection of that into the graph vocabulary; fetching it is the caller's job.
//
// ONE NODE PER CRATE, INCLUDING THE ONES WITH NO VERBS. That is the 2026-09-01 decision and it is the
// whole reason the roster exists rather than just the catalog: the node's job is MAINTENANCE, and
// `bsc-util` exposes no verb while being the crate whose change reaches most of the workspace — so it
// is exactly the one that needs an owner. Whether a crate has verbs is a FACET on the node, never the
// criterion for having one.
import {
  surfaceNodeId,
  dependsOnEdgeId,
  verbNodeId,
  nounNodeId,
  verbOfEdgeId,
  type GRawNode,
  type GRawEdge,
  type GRole,
} from "@/features/glance/lib/glanceGraph";
import type { GlanceData } from "@/features/glance/lib/glanceData";

/** One row of `bsc surface crates --json`. */
export interface SurfaceRosterRow {
  /** The cargo PACKAGE name — the node key. Not the directory (`crates/data` is `bsc-data`) and not
   *  the lib target (`bsc-llm`'s is `llm`). */
  crate: string;
  /** The workspace member path, as the root Cargo.toml lists it. */
  path: string;
  /** Whether this crate exposes any `bsc` verb. A FACET — a false here still gets a node. */
  surface: boolean;
  /** The verbs it serves, in catalog order. Empty for a crate with no surface. */
  verbs: string[];
  /** Its internal cargo dependencies, by package name. */
  dependsOn: string[];
}

/** The projected band: one node per crate, one edge per internal dependency. */
export interface SurfaceGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/** The three kinds of crate, by HOW YOU USE IT — the question a reader of this graph is asking. */
export type CrateKind = "surface" | "library" | "program";

/** Which accent each kind borrows. See {@link crateKind} for why these three and not others. */
export const CRATE_KIND_ROLE: Record<CrateKind, GRole> = {
  surface: "service", // something you CALL — `bsc <verb>`
  library: "infra",   // something others BUILD ON
  program: "client",  // something that RUNS on its own
};

/**
 * Classify one crate. Disjoint and exhaustive over the real roster: MEASURED 43 / 14 / 3 of 60.
 *
 * The axis is HOW THE CRATE IS USED, which is what a "kind" means here and what the graph is read for:
 *
 *  - `surface` — it answers `bsc <verb>`. The catalog says so, so this is a fact, not a heuristic.
 *  - `library` — no verb, but other crates depend on it. `bsc-util` is the extreme: no verb at all and
 *    44 dependents, which is exactly why the 2026-09-01 decision gave every crate a node.
 *  - `program` — no verb AND nothing depends on it: it is its own binary. `base-studio-code` (the app),
 *    `bsc-agent`, `bsc-hook`.
 *
 * FAN-IN IS THE DISCRIMINATOR between the last two, not a name pattern. `bsc-agent` and `bsc-hook` look
 * like libraries by name and are not; `channel` and `research` look like programs and are not. A name
 * heuristic would have got four of seventeen wrong, silently.
 */
export function crateKind(row: SurfaceRosterRow, fanIn: number): CrateKind {
  if (row.surface) return "surface";
  return fanIn > 0 ? "library" : "program";
}

/**
 * Project the crate roster into surface nodes + crate-dependency edges.
 *
 * `health` is `off` and `activity` is `idle` DELIBERATELY: a crate has no health signal yet. Marking
 * every crate `healthy` would assert something nobody measured, and this graph's whole point is that
 * the dot means something. Deriving real health (from `bsc errors`, or the gate) is a later
 * increment; until then the node says "no signal" rather than "fine".
 *
 * An edge to a crate that is NOT in the roster is DROPPED rather than drawn. A dangling edge is worse
 * than a missing one: the layout would carry a node id nothing renders, and the dependency count
 * shown on a node would include a target the user cannot click.
 */
export function surfaceGraph(roster: SurfaceRosterRow[]): SurfaceGraph {
  const known = new Set(roster.map((r) => r.crate));

  // How many OTHER crates build on each one — the signal that separates a library from a program.
  const fanIn = new Map<string, number>();
  for (const r of roster) {
    for (const dep of r.dependsOn) {
      if (dep !== r.crate && known.has(dep)) fanIn.set(dep, (fanIn.get(dep) ?? 0) + 1);
    }
  }

  const nodes: GRawNode[] = roster.map((r) => {
    const kind = crateKind(r, fanIn.get(r.crate) ?? 0);
    return {
      id: surfaceNodeId(r.crate),
      slug: r.crate,
      kind: "surface" as const,
      // The COLOUR channel. Not arbitrary: a library IS infrastructure others stand on, a surface IS a
      // service you call, and a program IS a client — the role vocabulary already means these things,
      // so a reader who knows the L1 legend is not learning a second code.
      role: CRATE_KIND_ROLE[kind],
      // The WORD channel, so the distinction survives colour-blindness, a greyscale screenshot and a
      // reader who has not memorised the legend. A colour alone is a cipher; a caption is a fact.
      roleLabel: kind,
      health: "off" as const,
      activity: "idle" as const,
    };
  });

  // TRANSITIVELY REDUCED — draw only the edges that are not already implied by a longer path.
  //
  // The full cargo graph is 230 edges over 60 crates and it made the drill LAG. Reachability is
  // identical either way: an edge A→C is dropped only when some A→B→…→C already exists, so nothing a
  // reader could follow is lost. MEASURED on the real roster: 230 → 123 edges (46% fewer), and the
  // hub collapse is the point — `bsc-util` went from 44 converging lines to 5, `bsc-cli-util` from
  // 46 to 19. Nearly every crate reaches `bsc-util` THROUGH `bsc-cli-util`, so 39 of those 44 lines
  // were restating a fact the graph already showed.
  //
  // A CAP was the alternative and is worse: dropping the Nth edge of a busy node hides a real
  // dependency and which one you lose depends on iteration order. A reduction is information-
  // preserving and deterministic. Safe because the graph is a DAG (cargo cannot express a cycle in
  // normal dependencies) — on a cyclic graph a transitive reduction is not unique.
  const adj = new Map<string, Set<string>>();
  for (const r of roster) {
    adj.set(r.crate, new Set(r.dependsOn.filter((d) => d !== r.crate && known.has(d))));
  }
  // Reachability per node, computed over a post-order so a node's successors are always done first.
  const reach = new Map<string, Set<string>>();
  const visiting = new Set<string>();
  const settle = (u: string): Set<string> => {
    const done = reach.get(u);
    if (done) return done;
    // `visiting` is belt-and-braces: the DAG is asserted by its own test, but a malformed roster must
    // not hang the cockpit. A back-edge simply contributes nothing rather than recursing forever.
    if (visiting.has(u)) return new Set();
    visiting.add(u);
    const acc = new Set<string>();
    for (const v of adj.get(u) ?? []) {
      acc.add(v);
      for (const w of settle(v)) acc.add(w);
    }
    visiting.delete(u);
    reach.set(u, acc);
    return acc;
  };
  for (const r of roster) settle(r.crate);

  const edges: GRawEdge[] = [];
  const seen = new Set<string>();
  for (const r of roster) {
    const deps = adj.get(r.crate) ?? new Set();
    for (const dep of deps) {
      // Implied by a sibling? Then the path already says it, and the line is noise.
      let implied = false;
      for (const other of deps) {
        if (other !== dep && reach.get(other)?.has(dep)) {
          implied = true;
          break;
        }
      }
      if (implied) continue;
      const id = dependsOnEdgeId(r.crate, dep);
      if (seen.has(id)) continue;
      seen.add(id);
      edges.push({ id, from: surfaceNodeId(r.crate), to: surfaceNodeId(dep), kind: "depends-on" });
    }
  }
  return { nodes, edges };
}

// `dependentCount` USED TO LIVE HERE. Rust owns it: `bsc surface drill` computes
// `"dependentCount": dependents.len()` (crates/bsc/src/main.rs) and ships it as a field on
// `CrateDrillDoc`, so the TypeScript copy answered the same question a second time and was called by
// nothing but its own test. `glanceFoldsAreCalled.test.ts` found it the moment that guard stopped
// counting a generated copy of a declaration as a call site.
/**
 * Fold the crate roster into a DRILL's graph — the app's own project drill, beside its studio sessions.
 *
 * NOT AN L0 BAND, AND THAT IS THE WHOLE POINT. `glanceData` carries the epitaph of the first attempt:
 * one node per active `bsc` subcommand and no edge at all, because the `invokes` edge runs
 * session→surface and L0 has no session node to draw one from. It left 33 permanently unconnected
 * nodes beside the project network — an inventory of the CLI rendered as if it were part of the
 * project graph. The `surfaces` parameter was deleted rather than kept and ignored, precisely so a
 * later reader would not put it back.
 *
 * Two things make this different rather than a repeat, and both are the 2026-09-01 decisions:
 * the node is keyed on the CRATE (so `bsc-util`, which has no verb and reaches 40 crates, gets one),
 * and the band HAS EDGES — `depends-on`, derived from cargo metadata. Structure is exactly what the
 * removed band lacked.
 *
 * Returns `data` UNCHANGED on an empty roster. A failed read must leave what is already drawn alone:
 * blanking the band on a transient error would make every crate vanish from the cockpit, which is the
 * rule the integration band states for the same reason.
 */
export function withSurfaceNodes(data: GlanceData, roster: SurfaceRosterRow[]): GlanceData {
  if (!roster.length) return data;
  const { nodes, edges } = surfaceGraph(roster);
  const present = new Set(data.rawNodes.map((n) => n.id));

  // EVERY CRATE CARRIES ITS REPO, or the drill stops separating by repository.
  //
  // `bandNodesByRepo` groups a drill's nodes on `n.repo` and leaves anything without one UNGROUPED —
  // so crates with no repo scattered through the whole graph instead of sitting with the repository
  // they live in. That was a regression the moment these stopped being fenced band nodes, because the
  // fence had been doing the separating by accident.
  //
  // The repo is taken from the nodes ALREADY in this drill rather than passed in: those are the
  // streams, and `withStreamRepos` has already stamped each with the repo from the plan — so a crate
  // joins the same band as the streams that own it, spelled exactly the same way. A roster is ONE
  // cargo workspace, hence one repository, which is why a single modal value is correct here and not
  // a simplification.
  //
  // With no repo to be had (a drill whose streams carry none) the crates are left UNSTAMPED rather
  // than given an invented one — ungrouped is honest, a wrong band is not.
  const repoTally = new Map<string, number>();
  for (const n of data.rawNodes) {
    if (n.repo) repoTally.set(n.repo, (repoTally.get(n.repo) ?? 0) + 1);
  }
  let repo: string | undefined;
  let best = 0;
  for (const [r, count] of repoTally) {
    if (count > best) {
      best = count;
      repo = r;
    }
  }

  const add = nodes.filter((n) => !present.has(n.id)).map((n) => (repo ? { ...n, repo } : n));
  if (!add.length) return data;
  // Every id this drill will hold once `add` lands — an edge is kept only if BOTH ends resolve, so a
  // node already drawn under another kind cannot acquire a dangling dependency line.
  const known = new Set([...present, ...add.map((n) => n.id)]);
  const seen = new Set(data.rawEdges.map((e) => e.id));
  const addEdges = edges.filter(
    (e) => !seen.has(e.id) && known.has(e.from) && known.has(e.to),
  );
  return { ...data, rawNodes: [...data.rawNodes, ...add], rawEdges: [...data.rawEdges, ...addEdges] };
}
/** One noun's row in `bsc surface drill <crate> --json`. */
export interface CrateDrillNoun {
  noun: string;
  status: string;
  catalog: "projected" | "unreachable";
  /** NULL when the crate serves this noun but publishes no `CmdDoc` catalog — distinct from empty. */
  verbs: { verb: string; summary: string; usage: string }[] | null;
}

/** The whole of `bsc surface drill <crate> --json`. */
export interface CrateDrillDoc {
  crate: string;
  path: string;
  surface: boolean;
  nouns: CrateDrillNoun[];
  dependsOn: string[];
  dependents: string[];
  dependentCount: number;
}

/**
 * THE SECOND LAYER — the NOUNS a crate serves, each rooting its own verbs.
 *
 * MAINTAINER 2026-09-02: "we should have the noun as the root of these graphs." The first cut rooted
 * the CRATE and hung every verb off it, which flattened `logs`/`metrics`/`perf` into one fan and lost
 * the thing a reader is actually navigating — you run `bsc logs sessions`, not `bsc logs-crate
 * sessions`. The noun IS the command; the crate is where it happens to be implemented.
 *
 * So a multi-noun crate yields a FOREST, one root per noun. That is the honest shape: those really are
 * three separate commands that happen to share a compilation unit.
 *
 * A NOUN WITH NO REACHABLE CATALOG IS STILL DRAWN, and this reverses the first cut deliberately.
 * Rooted on the crate, an empty cluster asserted the crate offered something it did not. Rooted on the
 * noun, the node says `bsc metrics` EXISTS and has no verb catalog — which is true and is exactly what
 * a reader wanting to know what they can run needs to see. It is captioned so the emptiness reads as a
 * fact rather than as a load that failed.
 *
 * A crate with NO nouns at all — a library or a program — yields just its own node, so the layer never
 * renders blank, which would read as a failed load rather than as "nothing to call here".
 */
export function crateDrillGraph(doc: CrateDrillDoc): GlanceData {
  const kind = crateKind(
    { crate: doc.crate, path: doc.path, surface: doc.surface, verbs: [], dependsOn: doc.dependsOn },
    doc.dependentCount,
  );
  const rawNodes: GRawNode[] = [];
  const rawEdges: GRawEdge[] = [];

  for (const noun of doc.nouns) {
    const rootId = nounNodeId(noun.noun);
    rawNodes.push({
      id: rootId,
      slug: noun.noun,
      kind: "surface" as const,
      role: CRATE_KIND_ROLE.surface,
      // The caption names the CRATE, so a reader knows where this command lives without leaving the
      // layer — the fact the crate root used to carry, kept where it is still useful.
      roleLabel: doc.crate,
      health: "off" as const,
      activity: "idle" as const,
    });

    for (const v of noun.verbs ?? []) {
      const id = verbNodeId(noun.noun, v.verb);
      if (rawNodes.some((x) => x.id === id)) continue;
      rawNodes.push({
        id,
        slug: v.verb,
        kind: "surface" as const,
        role: CRATE_KIND_ROLE.surface,
        // Its NOUN, which is what tells `bsc logs summary` from `bsc perf summary`.
        roleLabel: noun.noun,
        health: "off" as const,
        activity: "idle" as const,
      });
      // VERB → NOUN, and the direction is the LAYOUT. The engine lays layers left→right and puts
      // whatever an edge points AT on the left, so `noun → verb` placed each verb to the LEFT of its
      // own noun — backwards for a left-to-right reader. Pointing the verb AT its noun puts the noun
      // on the left with its verbs fanning right, which is the reading order.
      rawEdges.push({
        id: verbOfEdgeId(doc.crate, noun.noun, v.verb),
        from: id,
        to: rootId,
        kind: "verb-of",
      });
    }
  }

  // Nothing to call: show the crate itself rather than an empty canvas.
  if (!rawNodes.length) {
    rawNodes.push({
      id: surfaceNodeId(doc.crate),
      slug: doc.crate,
      kind: "surface" as const,
      role: CRATE_KIND_ROLE[kind],
      roleLabel: kind,
      health: "off" as const,
      activity: "idle" as const,
    });
  }
  return { rawNodes, rawEdges, sample: false };
}

// The FEATURE node projection (`a-feature-is-a-node`) — turn the plan's feature roster + its stream
// roster into Glance nodes and edges.
//
// The rosters come from `bsc plan feature list --json` and `bsc plan fleet get --full`. This module is
// the PURE projection of those into the graph vocabulary; fetching them is the caller's job, exactly
// as `surfaceNodes.ts` splits the crate roster from its projection.
//
// ONE NODE PER FEATURE, INCLUDING THE ONES WITH NO STREAMS. Same reasoning that gives a verb-less
// crate a node: a lane nobody has staffed is precisely the one worth seeing. Six of studio-code's 44
// features had no stream when this was written, and a projection that dropped them would have made
// the gap invisible in the one view that exists to show gaps.
import type { GlanceData } from "@/features/glance/lib/glanceData";
import {
  featureNodeId,
  featureRequiresNodeId,
  belongsToEdgeId,
  // The project→library `requires` edge id, reused rather than re-minted: a feature requiring a record
  // is the same relationship the L0 graph already draws, and a second id scheme for it would make the
  // same edge unequal to itself across the two views.
  requiresEdgeId,
  type GRawNode,
  type GRawEdge,
} from "@/features/glance/lib/glanceGraph";

/** One row of `bsc plan feature list --json`. */
export interface FeatureRow {
  slug: string;
  name?: string;
  /** The records this feature declares it needs. A bare id, or an entry carrying its provenance —
   *  the two shapes `RequiredRef` holds, and the reason the node can say WHO asked for a record. */
  requires?: Array<string | { id: string; by?: string; note?: string }>;
}

/** One row of the fleet's `streams` array, lean or full. */
export interface StreamRow {
  id: string;
  name?: string;
  /** `owner/name`, exactly as the plan records it. The fleet BANDS nodes by this
   *  (`withStreamRepos` → `glance-graph`), and a feature node that carries none lands in the
   *  unbanded group — which is how folding the streams away removed the repository separation. */
  repo?: string;
  /** Which feature it belongs to. ABSENT falls back to the stream's own id, which is how the 37
   *  streams whose id already IS a feature slug resolve — the same rule the launch applies, restated
   *  here rather than assumed, because a projection that disagreed with the launch would draw a graph
   *  of a fleet that does not exist. */
  feature?: string;
  kind?: string;
}

/** The projected band and its drill. */
export interface FeatureGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/** Which feature a stream belongs to — its own `feature`, else its id. See {@link StreamRow.feature}. */
export function streamFeature(s: StreamRow): string {
  const f = (s.feature ?? "").trim();
  return f || s.id;
}

/** The id of a required entry, whichever shape it takes. */
export function requiredId(r: string | { id: string }): string {
  return typeof r === "string" ? r : r.id;
}

/** Who asked for a required entry, when it says. A bare id carries no author — absent, never invented. */
export function requiredBy(r: string | { id: string; by?: string }): string | undefined {
  return typeof r === "string" ? undefined : r.by;
}

/** Every repo `slug` has streams in, in first-appearance order, and how many in each. */
function reposOf(streams: StreamRow[], slug: string): Map<string, number> {
  const out = new Map<string, number>();
  for (const s of streams) {
    if (streamFeature(s) !== slug) continue;
    const r = (s.repo ?? "").trim();
    if (r) out.set(r, (out.get(r) ?? 0) + 1);
  }
  return out;
}

/**
 * The repo a feature with NO streams bands under — the plan's dominant one.
 *
 * There is nothing on the feature itself to derive from, so this is a display default rather than a
 * claim about ownership. It is the right default because the alternative is what the maintainer
 * reported: an unbanded node sits LEFT of the repo fence with the director and the architect, so
 * `help` and `settings` read as project-level actors rather than as the unstaffed features they are.
 * Saying "probably the main repo" is a smaller error than saying "belongs to no repository".
 */
function dominantRepo(streams: StreamRow[]): string | undefined {
  const n = new Map<string, number>();
  for (const s of streams) {
    const r = (s.repo ?? "").trim();
    if (r) n.set(r, (n.get(r) ?? 0) + 1);
  }
  let best: string | undefined;
  for (const [r, c] of n) if (!best || c > (n.get(best) ?? 0)) best = r;
  return best;
}

/**
 * The FEATURE BAND — one node per feature, carrying how many streams it owns.
 *
 * The stream count rides on the node so the band answers "how big is this lane" without a drill. It is
 * the number a reader is actually scanning for: `teams-personas` owning 20 streams and `cad` owning one
 * are different kinds of thing, and a band of identically-sized cards would hide that.
 *
 * DETERMINISTIC — features in roster order, so two renders of the same plan diff meaningfully.
 */
export function featureBand(features: FeatureRow[], streams: StreamRow[]): FeatureGraph {
  const dominant = dominantRepo(streams);
  const nodes: GRawNode[] = features.flatMap((f) => {
    const repos = reposOf(streams, f.slug);
    // ONE NODE PER REPO THE FEATURE HAS WORK IN. A feature spanning repositories really does have work
    // in each, so a majority pick would erase the minority and leaving it unbanded would say it belongs
    // to none. `mobile-tunnel` is the live case: 1 stream in base-studio-code, 2 in mobile.
    //
    // The DUPLICATION IS SAFE because cross-repo coherence is not this graph's job — it is enforced
    // through the components and algorithms graphs and their relationships (maintainer, 2026-09-03).
    //
    // No streams at all ⇒ one node under the plan's dominant repo; see {@link dominantRepo}.
    const bands: { repo?: string; n: number }[] =
      repos.size > 0 ? [...repos].map(([repo, n]) => ({ repo, n })) : [{ repo: dominant, n: 0 }];
    return bands.map(({ repo, n }) => ({
      // The suffix ONLY when the feature actually spans, so the ids that already work do not churn.
      id: featureNodeId(f.slug, repos.size > 1 ? repo : undefined),
      slug: f.slug,
      kind: "feature" as const,
      // `service` — a feature is a CAPABILITY this product offers, which is the closest the role
      // vocabulary has. The size lives in `roleLabel` rather than in the colour.
      role: "service" as const,
      // Only THIS band's streams. A per-repo node claiming the whole feature's count would print the
      // same number in both bands, and neither would be checkable against what is under it.
      //
      // `0 streams` is stated rather than omitted: an unstaffed lane rendering as a blank card is
      // indistinguishable from a rendering bug.
      roleLabel: `${n} streams`,
      // THE REPO BAND, rebuilt on the coarse node. `withStreamRepos` stamps this per STREAM and the
      // layout bands by it, so a feature carrying none lands ungrouped beside the director — which is
      // exactly what removed the repository separation when the streams stopped being drawn.
      ...(repo ? { repo } : {}),
      health: "off" as const,
      activity: "idle" as const,
    }));
  });
  // The band draws no edges between features. `dependsOn` on a feature is the roadmap DAG — a
  // SEQUENCING hint, not a dependency the code has — and drawing it here would read as the same kind
  // of line the crate band uses for a real cargo edge.
  return { nodes, edges: [] };
}

/**
 * ONE FEATURE'S DRILL — its streams beneath it, and the records it requires beside them.
 *
 * Two node kinds because they answer two different questions. A STREAM is a lane of this project's own
 * work, with a worktree and a worker; a REQUIRED RECORD is something from the shared graphs this
 * feature builds against and does not own. Collapsing them would suggest a worker can edit both, and
 * the whole point of `requires` is that the second kind lives somewhere else.
 *
 * A required node names WHICH STORE answers it, because `bsc graph impl get` and `bsc ui get` are
 * different commands: a drill that guessed would send a reader to one that returns nothing for half
 * the list — the same reason the launch block resolves the store rather than assuming.
 */
export function featureDrill(
  feature: FeatureRow,
  streams: StreamRow[],
  /** Which store holds a record id, when known. `undefined` ⇒ the drill says so rather than guessing. */
  storeOf: (recordId: string) => "algorithms" | "components" | undefined = () => undefined,
): FeatureGraph {
  // THE FEATURE ITSELF IS THE ROOT OF ITS OWN DRILL, and it was missing. Every edge below names
  // `featureNodeId(feature.slug)`, so without this node the whole drill dangled: the streams rendered
  // with nothing to hang from, which is exactly what a reader sees as "no root".
  //
  // `featureBand` filters its edges to the nodes it emits (`known.has(e.from) && known.has(e.to)`);
  // this function had no such filter, so the dangling edges went straight into `buildGraph`. The band
  // was careful and the drill was not — hence `emitsNoDanglingEdge` in the tests, which asserts the
  // property for BOTH rather than trusting either.
  const nodes: GRawNode[] = [
    {
      id: featureNodeId(feature.slug),
      slug: feature.slug,
      kind: "feature" as const,
      role: "service" as const,
      roleLabel: `${streams.filter((s) => streamFeature(s) === feature.slug).length} streams`,
      health: "off" as const,
      activity: "idle" as const,
    },
  ];
  const edges: GRawEdge[] = [];

  const mine = streams.filter((s) => streamFeature(s) === feature.slug);
  for (const s of mine) {
    nodes.push({
      // THE STREAM'S OWN ID, which is the id the FLEET drill gives the same lane
      // (`glance-fleet.ts`: `nodeId: s.id`) — and panes bind as `fleetPaneId(drill, nodeId)`. Minting
      // `fstream:<feature>:<stream>` here gave one lane two identities depending on which graph you
      // arrived through, and only the fleet's resolved to a pane: the node said `session` and behaved
      // like a label. A worker's session must be the SAME session however the user navigated to it.
      id: s.id,
      slug: s.id,
      kind: "session" as const,
      // `client` — something that RUNS on its own, which is exactly what a stream is: a lane with a
      // worktree and a worker of its own.
      role: "client" as const,
      roleLabel: s.kind && s.kind !== "feature" ? s.kind : "stream",
      health: "off" as const,
      activity: "idle" as const,
    });
    edges.push({
      id: belongsToEdgeId(feature.slug, s.id),
      from: s.id,
      to: featureNodeId(feature.slug),
      kind: "belongs-to" as const,
    });
  }

  for (const r of feature.requires ?? []) {
    const id = requiredId(r);
    const store = storeOf(id);
    const by = requiredBy(r);
    nodes.push({
      id: featureRequiresNodeId(feature.slug, id),
      slug: id,
      kind: "library" as const,
      // `infra` — something others BUILD ON, the same role the crate band gives a library. A required
      // record is precisely that: shared, and not this feature's to edit.
      role: "infra" as const,
      // The store, then who asked. Both are facts a reader needs before acting: which command reads it,
      // and whether this entry was a director's seed or a worker's discovery.
      roleLabel: `${store ?? "unresolved"}${by ? ` · by ${by}` : ""}`,
      health: store ? ("off" as const) : ("warning" as const),
      // An id in NEITHER store is a dangling reference, and it is surfaced here rather than dropped —
      // `requires` is deliberately not validated at plan-write time, so a drill is one of the first
      // places a typo can become visible.
      ...(store ? {} : { reason: "in neither graph" }),
      activity: "idle" as const,
    });
    edges.push({
      id: requiresEdgeId(feature.slug, featureRequiresNodeId(feature.slug, id)),
      from: featureNodeId(feature.slug),
      to: featureRequiresNodeId(feature.slug, id),
      kind: "requires" as const,
    });
  }
  return { nodes, edges };
}


/**
 * FOLD THE FEATURE BAND INTO A DRILL — the call site `featureBand` existed six hours without.
 *
 * `a-feature-is-a-node` shipped the projection with three passing tests and nothing calling it, so the
 * band did not exist in the running app and no gate could tell. That is the second time this repo has
 * done it — `glanceFoldsAreCalled.test.ts` was written the first time, and its header says the whole
 * thing: A GRAPH FOLD WITH NO CALLER IS A NODE NOBODY SEES.
 *
 * Shaped exactly like [`withSurfaceNodes`], because the constraints are the same ones:
 *
 * - EMPTY IN, UNCHANGED OUT. A project with no features must cost nothing, not an empty band.
 * - AN ID ALREADY PRESENT IS NOT RE-ADDED, so folding twice is folding once.
 * - AN EDGE SURVIVES ONLY IF BOTH ENDS RESOLVE. A feature node drawn under some other kind must not
 *   acquire a dangling line, and the drill is assembled from several folds in sequence.
 */
export function withFeatureNodes(
  data: GlanceData,
  features: FeatureRow[],
  streams: StreamRow[],
): GlanceData {
  if (!features.length) return data;
  const { nodes, edges } = featureBand(features, streams);

  // THE FEATURE REPLACES THE STREAMS IT COVERS — it does not sit on top of them.
  //
  // This fold used to only ADD, so `buildRealFleetData`'s 89 flat stream nodes stayed exactly where
  // they were and 27 feature cards rendered over them. Both plans on one canvas: the maintainer read
  // that as "I'm still seeing the old plan" four times across two days, and every fix in between —
  // the re-mapping, the band, the drill wiring, the missing root, the dropped `feature` field — was
  // real and none of them could have helped, because they made the NEW layer correct while the OLD
  // one kept drawing underneath.
  //
  // A stream a feature owns is reachable by drilling that feature (`featureDrill`), so drawing it
  // flat here says the coarse node is decoration rather than the level you navigate.
  const slugs = new Set(features.map((f) => f.slug));
  // stream id → the feature node standing for it. Also the redirect table below.
  const standsFor = new Map<string, string>();
  for (const s of streams) {
    const f = streamFeature(s);
    if (!slugs.has(f)) continue;
    // TO THE NODE FOR ITS OWN REPO. A spanning feature draws one node per band, so a mobile stream
    // must fold onto the mobile node and a desktop stream onto the desktop one — otherwise the
    // director's `manages` would all land on whichever band happened to be first, and the other band's
    // node would sit there unmanaged.
    const spans = reposOf(streams, f).size > 1;
    const repo = (s.repo ?? "").trim();
    standsFor.set(s.id, featureNodeId(f, spans && repo ? repo : undefined));
  }

  const present = new Set(data.rawNodes.map((n) => n.id));
  const add = nodes.filter((n) => !present.has(n.id));
  // Nothing to add AND nothing to remove ⇒ the graph is already what it should be.
  if (!add.length && !standsFor.size) return data;

  // A stream belonging to NO feature stays drawn. Removing it would hide unassigned work, which is
  // the one thing this view must never do — an unstaffed lane is exactly what a reader is scanning
  // for, and it would vanish with no node to notice it by.
  const keptNodes = data.rawNodes.filter((n) => !standsFor.has(n.id));
  const known = new Set([...keptNodes.map((n) => n.id), ...add.map((n) => n.id)]);

  // THE FEATURE INHERITS THE RELATIONSHIPS OF THE STREAMS IT STANDS FOR — it does not get a fresh
  // edge minted for it.
  //
  // `fleetToOrg` already draws `director manages <stream>` for every stream, through `archOf`, which
  // lets a TEAM author a different archetype for a persona pair. Minting a new `manages` edge here
  // would discard that authored value and quietly disagree with the team graph; redirecting keeps
  // whatever the edge actually said. It also generalises for free — anything that pointed at a
  // stream now points at its feature, without this fold needing to know who or why.
  const redirect = (id: string) => standsFor.get(id) ?? id;
  const rerouted: GRawEdge[] = [];
  const seenPair = new Set<string>();
  for (const e of data.rawEdges) {
    // A STREAM-TO-STREAM EDGE IS NOT A FEATURE-TO-FEATURE FACT, and folding it invents claims the
    // plan never made. MEASURED on studio-code: 208 `dependsOn` edges between streams, ZERO cycles
    // among them — and 20 cycles among features once folded (`cli-platform → cad → cli-platform`,
    // `planner → console → planner`, eighteen more). They flooded the coordination-hazard pane and
    // hid the list behind deadlocks that do not exist.
    //
    // Collapsing a DAG's nodes into groups manufactures cycles: one cli-platform stream depending on
    // a cad stream while some cad stream depends on a cli-platform one is perfectly acyclic at stream
    // level. `featureBand` had already ruled on this — "the band draws no edges between features,
    // `dependsOn` on a feature is a SEQUENCING hint, not a dependency the code has" — and folding
    // every edge reintroduced exactly what that forbids.
    //
    // So only edges from OUTSIDE the covered set fold: the director's `manages` becomes
    // `director manages <feature>`, while a stream's own dependency stays a stream's own business.
    if (standsFor.has(e.from) && standsFor.has(e.to)) continue;
    const from = redirect(e.from);
    const to = redirect(e.to);
    // A stream's own edge to its feature says nothing the containment does not.
    if (from === to) continue;
    if (!known.has(from) || !known.has(to)) continue;
    // N streams under one feature collapse to ONE edge. Twenty parallel `director manages` lines
    // between the same pair is the same fact drawn twenty times.
    const key = `${from}|${to}|${e.kind}`;
    if (seenPair.has(key)) continue;
    seenPair.add(key);
    rerouted.push(
      from === e.from && to === e.to ? e : { ...e, from, to, id: `${e.kind}:${from}>${to}` },
    );
  }

  const seen = new Set(rerouted.map((e) => e.id));
  const addEdges = edges.filter((e) => !seen.has(e.id) && known.has(e.from) && known.has(e.to));
  return { ...data, rawNodes: [...keptNodes, ...add], rawEdges: [...rerouted, ...addEdges] };
}

