        { id: ALGO, slug: "Dijkstra", kind: "library", library: "algo", role: "infra", health: "healthy", activity: "idle" },
        { id: SOUND, slug: "Chime", kind: "library", library: "sound", role: "infra", health: "healthy", activity: "idle" },
      ],
