describe("resolveGridAnchor (a vanished anchor must not blank every morph)", () => {
  const present = new Set(["a", "b", "c"]);

  it("keeps the stored anchor while its node is still in the graph", () => {
    expect(resolveGridAnchor("b", ["b", "c"], present)).toBe("b");
  });

  // THE BUG: the anchor is retained after its own morph closes, so the id outlives the node. The old
