import { describe, it, expect } from "vitest";
import {
  type AttemptOutcome,
  type AttemptRecord,
  type ConnectionState,
  type InstitutionConnector,
  CONNECTORS,
  backoff,
  capabilitiesAreWellFormed,
  capabilityFor,
  connectorFor,
  containsSecretBearingKey,
  decide,
  describe as describeConnection,
  lastAttempt,
  maskAccount,
  planConnections,
  sessionIsFresh,
  trailing,
} from "@/features/finance/lib/connection";

// SYNTHETIC FIXTURES ONLY. No real credential, account number or session belongs in this repo.
const NOW = "2026-07-01T12:00:00Z";
const ago = (minutes: number): string => new Date(Date.parse(NOW) - minutes * 60_000).toISOString().slice(0, 19) + "Z";

const attempt = (outcome: AttemptOutcome, minutesAgo = 60): AttemptRecord => ({ at: ago(minutesAgo), outcome });

const state = (over: Partial<ConnectionState> = {}): ConnectionState => ({
  connectorId: "discover",
  attempts: [],
  lockedOut: false,
  ...over,
});

const CONN = connectorFor("discover")!;

describe("AN AUTH FAILURE IS NEVER RETRIED", () => {
  it("stops on a rejected credential, and says why a second attempt is not free", () => {
    // One rejection can be a typo or a rotated password. A second automated attempt is how lockout
    // happens, and "I could not sync today" and "I cannot log in at all" are not the same cost.
    const a = decide(CONN, state({ attempts: [attempt("auth")] }), NOW);
    expect(a.kind).toBe("stop");
    expect(a.why).toContain("how an account gets locked");
    expect(a.why).toContain("bsc secret put");
  });

  it("stays stopped however long has passed and however fresh the session looks", () => {
    // No amount of elapsed time or session freshness may talk the policy into trying again — which
    // is why every stopping rule is checked before anything that acts.
    for (const minutesAgo of [1, 60, 60 * 24 * 30]) {
      const a = decide(
        CONN,
        state({ attempts: [attempt("auth", minutesAgo)], sessionSince: ago(1) }),
        NOW,
      );
      expect(a.kind).toBe("stop");
    }
  });

  it("RETRIES a transport failure, because that says nothing about the credential", () => {
    // The distinction between "the credential was rejected" and "the institution was not reached"
    // is the whole point of this module. Collapsing them into "it failed" loses the only fact that
    // decides whether trying again is safe.
    const a = decide(CONN, state({ attempts: [attempt("transport")] }), NOW);
    expect(a.kind).toBe("wait");
  });

  it("backs off further the more consecutive transport failures there are", () => {
    const one = decide(CONN, state({ attempts: [attempt("transport")] }), NOW);
    const three = decide(
      CONN,
      state({ attempts: [attempt("transport", 3), attempt("transport", 2), attempt("transport", 1)] }),
      NOW,
    );
    expect(one.kind).toBe("wait");
    expect(three.kind).toBe("wait");
    if (one.kind === "wait" && three.kind === "wait") {
      expect(three.untilMinutes).toBeGreaterThan(one.untilMinutes);
      expect(three.why).toContain("conspicuous");
    }
  });

  it("counts only the CONSECUTIVE trailing failures, so an old one does not compound forever", () => {
    const s = state({ attempts: [attempt("transport", 5), attempt("ok", 4), attempt("transport", 1)] });
    expect(trailing(s, "transport")).toBe(1);
    expect(lastAttempt(s)!.outcome).toBe("transport");
  });

  it("doubles and then caps", () => {
    expect(backoff(1, 5, 240)).toBe(5);
    expect(backoff(2, 5, 240)).toBe(10);
    expect(backoff(4, 5, 240)).toBe(40);
    expect(backoff(99, 5, 240)).toBe(240);
    expect(backoff(0, 5, 240)).toBe(5);
  });
});

describe("MFA is a handoff, not an obstacle to route around", () => {
  it("hands a challenge to the person rather than trying anything", () => {
    const a = decide(CONN, state({ attempts: [attempt("challenge")] }), NOW);
    expect(a.kind).toBe("hand-to-person");
    // Attempting to defeat a challenge is futile AND is itself the signal that flags a session.
    expect(a.why).toContain("gets a session flagged");
  });

  it("offers the manual path as the thing to do instead", () => {
    const a = decide(CONN, state({ attempts: [attempt("challenge")] }), NOW);
    expect(a.kind === "hand-to-person" && a.instead).toBe("file-drop");
    expect(capabilityFor(CONN, a)).toBe("file-drop");
  });

  it("stops on a changed layout instead of scraping plausible nonsense", () => {
    const a = decide(CONN, state({ attempts: [attempt("layout")] }), NOW);
    expect(a.kind).toBe("stop");
    expect(a.why).toContain("reads plausible nonsense");
  });

  it("stops on a locked account and does not pretend anything here can clear it", () => {
    for (const s of [state({ lockedOut: true }), state({ attempts: [attempt("locked")] })]) {
      const a = decide(CONN, s, NOW);
      expect(a.kind).toBe("stop");
      expect(a.why).toMatch(/institution|call to the institution/);
    }
  });
});

describe("a fresh session is the lockout-avoidance mechanism", () => {
  it("uses a young session rather than logging in at all", () => {
    const a = decide(CONN, state({ sessionSince: ago(60), attempts: [attempt("ok", 60)] }), NOW);
    expect(a.kind).toBe("use-session");
    expect(a.why).toContain("avoiding the login is what avoids the challenge");
  });

  it("logs in once the session has aged past its ttl", () => {
    const old = state({ sessionSince: ago(60 * 24 * 30), attempts: [] });
    expect(sessionIsFresh(old, NOW, 168)).toBe(false);
    expect(decide(CONN, old, NOW).kind).toBe("login");
  });

  it("treats a session dated in the future as not fresh rather than eternally fresh", () => {
    // A clock skew or a bad write should fail CLOSED. "Fresh forever" would silently stop
    // re-authenticating and every fetch after it would quietly return nothing.
    const skewed = state({ sessionSince: "2027-01-01T00:00:00Z" });
    expect(sessionIsFresh(skewed, NOW, 168)).toBe(false);
    expect(decide(CONN, skewed, NOW).kind).toBe("login");
  });

  it("will not log in twice in quick succession", () => {
    const a = decide(CONN, state({ attempts: [attempt("ok", 2)] }), NOW);
    expect(a.kind).toBe("wait");
    expect(a.why).toContain("draws attention");
  });

  it("logs in when there is no session, nothing blocking and the cooldown has passed", () => {
    const a = decide(CONN, state({ attempts: [attempt("ok", 600)] }), NOW);
    expect(a.kind).toBe("login");
  });

  it("logs in on a connection that has never been used", () => {
    expect(decide(CONN, state(), NOW).kind).toBe("login");
  });
});

describe("the manual path is never removed", () => {
  it("every packaged connector ends in file-drop, exactly once", () => {
    // Every automated path against a site somebody else controls will break, usually without
    // warning. A system that only works while the automation works is a system that stops working.
    for (const c of CONNECTORS) {
      expect(capabilitiesAreWellFormed(c)).toBe(true);
      expect(c.capabilities).toContain("file-drop");
      expect(c.capabilities[c.capabilities.length - 1]).toBe("file-drop");
    }
  });

  it("prefers the institution's own export over scraping the page", () => {
    // The export file is a contract they maintain. The DOM is not, and a scrape is far more visible
    // to whatever watches for automation.
    for (const c of CONNECTORS) {
      expect(c.capabilities[0]).toBe("export-download");
      expect(c.capabilities).not.toContain("dom-scrape");
    }
  });

  it("says every connector is UNVERIFIED and names what to expect", () => {
    expect(CONNECTORS.every((c) => c.verified === false)).toBe(true);
    expect(CONNECTORS.every((c) => (c.caveat ?? "").length > 0)).toBe(true);
    expect(CONNECTORS.every((c) => c.exportPath.length > 0)).toBe(true);
  });

  it("expects a challenge at all four — none of them is a plain password", () => {
    expect(CONNECTORS.every((c) => c.auth === "password-mfa")).toBe(true);
  });

  it("points every connector at an ingest profile", () => {
    expect(CONNECTORS.map((c) => c.profileId).sort()).toEqual([
      "bank-of-america",
      "capital-one",
      "chase",
      "discover",
    ]);
  });
});

describe("the secret never enters this layer", () => {
  it("finds a secret-bearing key at any depth", () => {
    expect(containsSecretBearingKey({ password: "x" })).toBe("password");
    expect(containsSecretBearingKey({ a: { b: [{ apiKey: "x" }] } })).toBe("apiKey");
    expect(containsSecretBearingKey({ a: { b: { otp: "1" } } })).toBe("otp");
    expect(containsSecretBearingKey([{ token: "t" }])).toBe("token");
    expect(containsSecretBearingKey({ sessionId: "s" })).toBe("sessionId");
  });

  it("passes what is legitimately there", () => {
    expect(containsSecretBearingKey({ secretId: "discover-login", account: "a@b.c" })).toBeUndefined();
    expect(containsSecretBearingKey(CONNECTORS)).toBeUndefined();
    expect(containsSecretBearingKey(state({ attempts: [attempt("auth")] }))).toBeUndefined();
  });

  it("survives a cycle instead of recursing forever", () => {
    const a: Record<string, unknown> = {};
    a.self = a;
    expect(containsSecretBearingKey(a)).toBeUndefined();
  });

  it("is a GUARD, not a filter — it reports rather than stripping", () => {
    // Silently removing a password would let a caller keep writing the code that put one there.
    const payload = { password: "x" };
    expect(containsSecretBearingKey(payload)).toBe("password");
    expect(payload.password).toBe("x");
  });

  it("masks an account wherever a person or a log will see it", () => {
    expect(maskAccount("kevin@example.com")).toBe("k****@example.com");
    expect(maskAccount("4111111111111234")).toBe("************1234");
    expect(maskAccount("abcd")).toBe("****");
    expect(maskAccount("ab")).toBe("**");
  });

  it("never prints an unmasked account in a description", () => {
    const line = describeConnection(CONN, { secretId: "discover-login", account: "kevin@example.com" }, decide(CONN, state(), NOW));
    expect(line).not.toContain("kevin@example.com");
    expect(line).toContain("k****@example.com");
    expect(line).toContain("Discover");
  });
});

describe("planConnections — the blocked ones first", () => {
  it("puts what needs a person above what is healthy", () => {
    // A list that buries the blocked connections under the working ones is a list nobody acts on.
    const plans = planConnections(
      CONNECTORS,
      [
        { connectorId: "discover", attempts: [attempt("ok", 600)], lockedOut: false },
        { connectorId: "chase", attempts: [attempt("auth")], lockedOut: false },
        { connectorId: "capital-one", attempts: [attempt("challenge")], lockedOut: false },
      ],
      NOW,
    );
    expect(plans.slice(0, 2).map((p) => p.institution)).toEqual(["Capital One", "Chase"]);
    expect(plans.slice(0, 2).every((p) => p.needsPerson)).toBe(true);
    expect(plans.slice(2).every((p) => !p.needsPerson)).toBe(true);
  });

  it("plans a connector that has no state at all rather than skipping it", () => {
    const plans = planConnections(CONNECTORS, [], NOW);
    expect(plans).toHaveLength(CONNECTORS.length);
    expect(plans.every((p) => p.action.kind === "login")).toBe(true);
    expect(plans.every((p) => p.capability === "export-download")).toBe(true);
  });

  it("routes a blocked connector to the manual path, not to its usual capability", () => {
    const plans = planConnections(CONNECTORS, [{ connectorId: "chase", attempts: [attempt("auth")], lockedOut: false }], NOW);
    const chase = plans.find((p) => p.institution === "Chase")!;
    expect(chase.capability).toBe("file-drop");
    expect(chase.needsPerson).toBe(true);
  });

  it("carries no secret-bearing key in anything it produces", () => {
    const plans = planConnections(CONNECTORS, [{ connectorId: "chase", attempts: [attempt("auth")], lockedOut: false }], NOW);
    expect(containsSecretBearingKey(plans)).toBeUndefined();
  });
});

describe("a connector nobody has heard of", () => {
  it("is undefined rather than a default", () => {
    expect(connectorFor("wells-fargo")).toBeUndefined();
  });

  it("is caught by the well-formedness check when its capabilities are wrong", () => {
    const bad: InstitutionConnector = { ...CONN, capabilities: ["export-download"] };
    expect(capabilitiesAreWellFormed(bad)).toBe(false);
    const backwards: InstitutionConnector = { ...CONN, capabilities: ["file-drop", "export-download"] };
    expect(capabilitiesAreWellFormed(backwards)).toBe(false);
  });
});

implementations.code:
//! Stored sessions, and the one question this side actually asks.
//!
//! THE DRIVER NEVER TYPES A CREDENTIAL. That is a consequence of never logging in unattended, and it
//! is the strongest property in this whole layer: a person signs in with their own browser, the
//! resulting session is stored, and everything automated only ever REUSES one. So no code path here
//! reads a password, and there is no password for a bug in it to leak. `bsc secret` still records
//! which pairings exist and whether they last worked — metadata, which is what it is for.
//!
//! # This is NARROWER than the TypeScript policy, deliberately
//!
//! `@/features/finance/lib/connection` decides among six actions — login, wait, hand over, stop. This
//! answers ONE question: may an unattended fetch happen right now? It is not a port of that function
//! and must not become one; two copies of a six-way decision in two languages is a divergence waiting
//! to happen, and the divergence would be in the direction of doing something unsafe.
//!
//! The contract between them is one-way and CONSERVATIVE: this may answer `Go` only where the general
//! policy would say `use-session`. Every other case is somebody's problem, not this function's, and it
//! says so rather than deciding. That asymmetry is why the narrow version is safe to have twice.
use std::time::{SystemTime, UNIX_EPOCH};

/// What happened last time something touched this institution.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Outcome {
    /// Signed in and got what we came for.
    Ok,
    /// The institution was NOT REACHED. Says nothing about the credential.
    Transport,
    /// The credential was REJECTED. Never retried, by anything, ever.
    Auth,
    /// MFA or a device check. A person is needed.
    Challenge,
    /// Signed in, but the page was not the page we expected.
    Layout,
    /// The institution says the account is locked.
    Locked,
}

impl Outcome {
    pub fn as_str(self) -> &'static str {
        match self {
            Outcome::Ok => "ok",
            Outcome::Transport => "transport",
            Outcome::Auth => "auth",
            Outcome::Challenge => "challenge",
            Outcome::Layout => "layout",
            Outcome::Locked => "locked",
        }
    }

    pub fn parse(s: &str) -> Option<Outcome> {
        Some(match s {
            "ok" => Outcome::Ok,
            "transport" => Outcome::Transport,
            "auth" => Outcome::Auth,
            "challenge" => Outcome::Challenge,
            "layout" => Outcome::Layout,
            "locked" => Outcome::Locked,
            _ => return None,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attempt {
    /// `YYYY-MM-DDTHH:MM:SSZ`.
    pub at: String,
    pub outcome: Outcome,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SessionState {
    pub connector: String,
    /// When the person last signed in. `None` means there is nothing stored to reuse.
    pub session_since: Option<String>,
    /// Most recent LAST.
    pub attempts: Vec<Attempt>,
    /// Set by a person, cleared by a person. Nothing automated writes this false.
    pub locked_out: bool,
}

/// The answer, and only ever about an UNATTENDED fetch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FetchVerdict {
    /// A stored session is usable right now.
    Go,
    /// Nothing is wrong; there is simply no session to reuse, and establishing one is attended.
    NeedsPerson(String),
    /// Something IS wrong and a person has to deal with the institution before anything retries.
    Blocked(String),
}

impl FetchVerdict {
    pub fn is_go(&self) -> bool {
        matches!(self, FetchVerdict::Go)
    }

    pub fn reason(&self) -> &str {
        match self {
            FetchVerdict::Go => "a stored session is still young enough to reuse",
            FetchVerdict::NeedsPerson(r) | FetchVerdict::Blocked(r) => r,
        }
    }
}

/// Seconds since the epoch for `YYYY-MM-DDTHH:MM:SSZ`, or `None` if it is not that.
///
/// Written out rather than pulled in: a date crate here would be a dependency the whole binary pays
/// for so that one comparison can be made, and the civil-days arithmetic is a known, closed form.
pub fn epoch_seconds(iso: &str) -> Option<i64> {
    let b = iso.as_bytes();
    if b.len() < 19 || b[4] != b'-' || b[7] != b'-' || (b[10] != b'T' && b[10] != b' ') || b[13] != b':' || b[16] != b':' {
        return None;
    }
    let num = |a: usize, z: usize| iso.get(a..z)?.parse::<i64>().ok();
    let (y, mo, d) = (num(0, 4)?, num(5, 7)?, num(8, 10)?);
    let (h, mi, s) = (num(11, 13)?, num(14, 16)?, num(17, 19)?);
    if !(1..=12).contains(&mo) || !(1..=31).contains(&d) || h > 23 || mi > 59 || s > 60 {
        return None;
    }
    // Howard Hinnant's days_from_civil: exact, branch-light, and correct across the leap rules.
    let y = if mo <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (mo + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    let days = era * 146_097 + doe - 719_468;
    Some(days * 86_400 + h * 3600 + mi * 60 + s)
}

/// `YYYY-MM-DDTHH:MM:SSZ` for right now — the only place a clock is read, so everything below it can
/// be handed a fixed time and tested.
pub fn now_iso() -> String {
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
    iso_from_epoch(secs)
}

pub fn iso_from_epoch(secs: i64) -> String {
    let (days, rem) = (secs.div_euclid(86_400), secs.rem_euclid(86_400));
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}Z", rem / 3600, (rem % 3600) / 60, rem % 60)
}

pub const DEFAULT_TTL_HOURS: i64 = 168;

/// Whether the stored session is young enough to reuse.
///
/// A FUTURE-DATED session is NOT fresh. Clock skew or a bad write would otherwise make one read as
/// fresh forever, so nothing would re-authenticate and every fetch after it would quietly return
/// nothing — a silent stop, which is the worst failure available here.
pub fn session_is_fresh(state: &SessionState, as_of: &str, ttl_hours: i64) -> bool {
    let (Some(since), Some(now)) = (state.session_since.as_deref().and_then(epoch_seconds), epoch_seconds(as_of))
    else {
        return false;
    };
    let age = now - since;
    age >= 0 && age < ttl_hours * 3600
}

/// May an unattended fetch happen right now?
///
/// The stopping cases are checked FIRST and unconditionally, so no amount of session freshness can
/// talk this into acting on a connection a person needs to look at.
pub fn may_fetch_unattended(state: &SessionState, as_of: &str, ttl_hours: i64) -> FetchVerdict {
    if state.locked_out {
        return FetchVerdict::Blocked(
            "the account is locked — only the institution clears that, and nothing here will try again in the meantime".into(),
        );
    }
    match state.attempts.last().map(|a| a.outcome) {
        Some(Outcome::Locked) => {
            return FetchVerdict::Blocked("the institution reported the account locked on the last attempt".into())
        }
        Some(Outcome::Auth) => {
            // Never, and not because of a count — because of what it was. Nothing here retries a
            // rejected credential, and no elapsed time changes that.
            return FetchVerdict::Blocked(
                "the credential was rejected last time — a second automated attempt is how an account gets locked. Update it with `bsc secret put`, then sign in once by hand.".into(),
            )
        }
        Some(Outcome::Challenge) => {
            return FetchVerdict::Blocked(
                "a verification challenge is waiting — sign in by hand to clear it; nothing here will try to route around one".into(),
            )
        }
        Some(Outcome::Layout) => {
            return FetchVerdict::Blocked(
                "the page was not what it was last time — a fetch against a changed layout reads plausible nonsense, so it stops rather than guessing".into(),
            )
        }
        _ => {}
    }

    if session_is_fresh(state, as_of, ttl_hours) {
        return FetchVerdict::Go;
    }
    FetchVerdict::NeedsPerson(match state.session_since {
        // Nothing is WRONG here. There is simply nothing to reuse, and establishing one is attended
        // by design — so this is a different answer from `Blocked`, and the caller should read it
        // as "your turn", not "something broke".
        Some(_) => "the stored session has aged out — sign in once and it is good for another week".into(),
        None => "no stored session — sign in once by hand and everything after that is unattended".into(),
    })
}

/// Record what an attempt did. Append-only: an attempt history that can be rewritten is not evidence,
/// and the `auth` entry is precisely the one something would be tempted to remove.
pub fn record(state: &mut SessionState, outcome: Outcome, at: &str) {
    state.attempts.push(Attempt { at: at.to_string(), outcome });
    if outcome == Outcome::Locked {
        state.locked_out = true;
    }
    if outcome == Outcome::Ok && state.session_since.is_none() {
        state.session_since = Some(at.to_string());
    }
}

/// Stamp a session as established — what the attended sign-in reports back.
pub fn established(state: &mut SessionState, at: &str) {
    state.session_since = Some(at.to_string());
    state.attempts.push(Attempt { at: at.to_string(), outcome: Outcome::Ok });
}


// ─────────────────────────────────────────────────────────────────────────────────────────────────
// The wire shape
//
// VALUES, not IO. The file handling belongs to the caller; what is worth pinning here is that a
// round trip loses nothing — a session store that silently drops the `auth` attempt on reload would
// re-enable exactly the retry the policy above exists to forbid.

/// Every state as one JSON value, keyed by connector.
pub fn to_json(states: &[SessionState]) -> serde_json::Value {
    serde_json::Value::Object(
        states
            .iter()
            .map(|s| {
                (
                    s.connector.clone(),
                    serde_json::json!({
                        "sessionSince": s.session_since,
                        "lockedOut": s.locked_out,
                        "attempts": s.attempts.iter().map(|a| serde_json::json!({
                            "at": a.at,
                            "outcome": a.outcome.as_str(),
                        })).collect::<Vec<_>>(),
                    }),
                )
            })
            .collect(),
    )
}

/// Read them back. An outcome nobody recognises is DROPPED with the attempt it belongs to rather
/// than defaulting to `ok` — a future version writing an outcome this one has never heard of must
/// not have it read as "everything is fine".
pub fn from_json(value: &serde_json::Value) -> Vec<SessionState> {
    let Some(obj) = value.as_object() else { return Vec::new() };
    let mut out: Vec<SessionState> = obj
        .iter()
        .map(|(connector, v)| SessionState {
            connector: connector.clone(),
            session_since: v.get("sessionSince").and_then(|x| x.as_str()).map(str::to_string),
            locked_out: v.get("lockedOut").and_then(|x| x.as_bool()).unwrap_or(false),
            attempts: v
                .get("attempts")
                .and_then(|x| x.as_array())
                .map(|xs| {
                    xs.iter()
                        .filter_map(|a| {
                            Some(Attempt {
                                at: a.get("at")?.as_str()?.to_string(),
                                outcome: Outcome::parse(a.get("outcome")?.as_str()?)?,
                            })
                        })
                        .collect()
                })
                .unwrap_or_default(),
        })
        .collect();
    out.sort_by(|a, b| a.connector.cmp(&b.connector));
    out
}

/// The state for one connector, or a blank one — a connector nobody has touched is not an error.
pub fn state_for(states: &[SessionState], connector: &str) -> SessionState {
    states
        .iter()
        .find(|s| s.connector == connector)
        .cloned()
        .unwrap_or_else(|| SessionState { connector: connector.to_string(), ..Default::default() })
}

/// Replace one connector's state, keeping every other.
pub fn upsert(states: &mut Vec<SessionState>, next: SessionState) {
    match states.iter_mut().find(|s| s.connector == next.connector) {
        Some(slot) => *slot = next,
        None => states.push(next),
    }
    states.sort_by(|a, b| a.connector.cmp(&b.connector));
}

#[cfg(test)]
mod tests {
