        );
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("'unknown-account'")));
        assert_eq!(p.net_worth.minor, 120_000);
    }

    #[test]
    fn another_currency_is_excluded_rather_than_converted() {
        let eur = Account { currency: "EUR".into(), ..acct("eu", Kind::Checking) };
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), eur],
            &[bal("checking", 120_000), bal("eu", 90_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts.len(), 1);
        assert_eq!(p.net_worth.minor, 120_000);
        assert!(p.problems.iter().any(|x| x.contains("not one number")));
    }

    #[test]
    fn an_investment_counts_toward_net_worth_but_never_toward_liquidity() {
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), acct("broker", Kind::Investment)],
            &[bal("checking", 120_000), bal("broker", 4_000_000)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, 4_120_000);
        assert_eq!(p.liquid.minor, 120_000);
    }

    #[test]
    fn an_unreconciled_ledger_carries_its_caveat_forward_instead_of_being_laundered() {
        let l = unverified_ledger(&[], "2026-06-30", "Chase export has no opening balance").unwrap();
        let p = position(&l, &[acct("checking", Kind::Checking)], &[bal("checking", 120_000)], Currency::USD);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("Chase export has no opening balance")));
        assert!(p.provenance.starts_with("UNVERIFIED"));
    }

    #[test]
    fn the_weighted_apr_weights_by_balance_not_by_account_count() {
        // $8,000 at 6.99% and $2,000 at 24.99% is not a 15.99% problem, and averaging the rates
        // would send somebody at the wrong debt first.
        let p = position(
            &led(&[]),
            &[card(), loan()],
            &[bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let w = p.weighted_apr.unwrap();
        assert!(w < (0.2499 + 0.0699) / 2.0, "weighted {w} should be below the plain mean");
        assert_eq!(w, 0.1059);
    }
}

//! Balances — and the conversion that has to happen at the boundary, not in somebody's head.
//!
//! # A person types what the statement prints
//!
//! That is the whole design constraint. A card statement says `2,431.07` and means you OWE it; a
//! chequing statement says `1,200.00` and means you HAVE it. The analysis needs both SIGNED by their
//! contribution to net worth, so something must convert — and asking a person to pre-negate a card
//! balance is asking them to get it wrong. They will type what they are looking at.
//!
//! So [`set_printed`] takes the printed figure and the account's KIND, and converts. Which means it
//! cannot store a balance for an account the registry has never heard of: without the kind, the sign
//! is not merely unknown, it is unknowable, and storing the number unconverted would put a debt into
//! net worth as an asset. The refusal is principled rather than fussy.
//!
//! # History is kept, and the LATEST is what gets used
//!
//! `position` rolls a balance forward with the transactions after it, so the most recent balance is
//! the one with the least rolling to do and therefore the least room for drift. Older ones are kept
//! rather than overwritten — a balance is an observation, and a store that forgets observations
//! cannot answer why a figure changed.
use crate::account::{Account, Kind};
use crate::money::{money, Currency, Money};
use crate::position::AccountBalance;
use crate::reconcile::StatementPeriod;

/// Record a balance from the figure a statement PRINTS.
///
/// The `kind` decides the sign, so this is the only place a printed number becomes a signed one.
pub fn from_printed(account: &str, as_of: &str, printed: Money, kind: Kind) -> AccountBalance {
    AccountBalance {
        account: account.to_string(),
        as_of: as_of.to_string(),
        balance: crate::position::from_statement_balance(kind, printed),
    }
}

/// The most recent balance for one account, or none.
///
/// LATEST, because `position` rolls forward from it: the nearer the observation, the fewer
/// transactions have to be applied on top and the less there is to get wrong.
pub fn latest_for<'a>(balances: &'a [AccountBalance], account: &str) -> Option<&'a AccountBalance> {
    balances.iter().filter(|b| b.account == account).max_by(|a, b| a.as_of.cmp(&b.as_of))
}

/// One balance per account — the set `position` actually consumes.
pub fn latest_each(balances: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut ids: Vec<&str> = balances.iter().map(|b| b.account.as_str()).collect();
    ids.sort();
    ids.dedup();
    ids.iter().filter_map(|id| latest_for(balances, id).cloned()).collect()
}

/// Add an observation, keeping every earlier one — unless it is the same account on the same DAY, in
/// which case it is a correction rather than a new observation and replaces it.
pub fn record(balances: &mut Vec<AccountBalance>, next: AccountBalance) {
    match balances.iter_mut().find(|b| b.account == next.account && b.as_of == next.as_of) {
        Some(slot) => *slot = next,
        None => {
            balances.push(next);
            balances.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
        }
    }
}

/// Accounts the registry declares that have no balance at all — the reason a position is missing a
/// row rather than showing it as zero.
pub fn without_balance(accounts: &[Account], balances: &[AccountBalance]) -> Vec<String> {
    accounts
        .iter()
        .filter(|a| latest_for(balances, &a.id).is_none())
        .map(|a| a.id.clone())
        .collect()
}

pub fn to_json(balances: &[AccountBalance]) -> serde_json::Value {
    serde_json::Value::Array(
        balances
            .iter()
            .map(|b| {
                serde_json::json!({
                    "account": b.account,
                    "asOf": b.as_of,
                    // SIGNED, and labelled as such — a reader that took this for a printed figure
                    // would negate every card balance back to wrong.
                    "signedMinor": b.balance.minor,
                    "currency": b.balance.currency.as_str(),
                })
            })
            .collect(),
    )
}

pub fn from_json(v: &serde_json::Value) -> Vec<AccountBalance> {
    let mut out: Vec<AccountBalance> = v
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or_default()
        .iter()
        .filter_map(|b| {
            Some(AccountBalance {
                account: b.get("account")?.as_str()?.to_string(),
                as_of: b.get("asOf")?.as_str()?.to_string(),
                balance: money(
                    b.get("signedMinor")?.as_i64()?,
                    Currency::new(b.get("currency").and_then(|c| c.as_str()).unwrap_or("USD")).unwrap_or(Currency::USD),
                ),
            })
        })
        .collect();
    out.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
    out
}

/// The balances the STATEMENTS themselves assert.
///
/// A running-balance column is the institution stating what the account held when the period closed,
/// so a period's closing figure is an observation of exactly the kind a person supplies by typing
/// what the statement prints — arriving by a path that cannot mistype it. Deriving it is why
/// `bsc fin position` can answer at all from an export alone, instead of declaring an account and
/// then reporting that it has no balance.
///
/// The bounds arrive ALREADY SIGNED (`statement::period_from_running` converts at the boundary, for
/// `reconcile`'s sake), so nothing here converts. That is the one thing to know before editing this:
/// routing these through [`from_printed`] would negate every card balance a second time.
pub fn from_periods(periods: &[StatementPeriod]) -> Vec<AccountBalance> {
    periods
        .iter()
        .map(|p| AccountBalance { account: p.account.clone(), as_of: p.to.clone(), balance: p.closing })
        .collect()
}

/// Merge derived balances under observed ones — **the observed wins on the same day**.
///
/// Both are observations, so neither is categorically better; the tie-break is which one a person
/// can correct. A statement's closing figure is fixed by the export, while a balance somebody typed
/// is what they were looking at in the account — often BECAUSE the derived one looked wrong. Letting
/// the derivation overwrite that would make the correction impossible to express, and it would do it
/// silently, which is the part that matters.
///
/// A stored balance on any OTHER day is kept as its own observation rather than replacing anything —
/// [`record`]'s same-account-same-day rule is the whole of the collision policy.
pub fn prefer_observed(stored: &[AccountBalance], derived: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut out = derived.to_vec();
    for b in stored {
        record(&mut out, b.clone());
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn period(account: &str, to: &str, closing: i64) -> StatementPeriod {
        crate::reconcile::usd_period(account, "2026-06-01", to, 0, closing)
    }

    #[test]
    fn a_statements_closing_figure_becomes_a_balance_at_the_period_end() {
        let out = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0].as_of, "2026-06-20", "the balance is observed when the period CLOSED");
        assert_eq!(out[0].balance.minor, 40_000);
    }

    #[test]
    fn a_balance_a_person_typed_beats_the_one_derived_for_that_same_day() {
        let derived = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        // They looked at the account and it said 385.12 — the export was stale, or a fee landed after.
        let stored = vec![AccountBalance {
            account: "chase-checking".to_string(),
            as_of: "2026-06-20".to_string(),
            balance: usd(38_512),
        }];
        let out = prefer_observed(&stored, &derived);
        assert_eq!(out.len(), 1, "same account, same day is ONE observation, not two");
        assert_eq!(out[0].balance.minor, 38_512, "the correction must survive the derivation");
    }

    #[test]
    fn a_stored_balance_on_another_day_is_kept_alongside_the_derived_one() {
        let derived = from_periods(&[period("chase-checking", "2026-06-20", 40_000)]);
        let stored = vec![AccountBalance {
            account: "chase-checking".to_string(),
            as_of: "2026-07-02".to_string(),
            balance: usd(12_000),
        }];
        let out = prefer_observed(&stored, &derived);
        assert_eq!(out.len(), 2, "different days are different observations");
        assert_eq!(latest_for(&out, "chase-checking").unwrap().balance.minor, 12_000);
    }

    fn acct(id: &str, kind: Kind) -> Account {
        Account {
            id: id.into(),
            institution: id.into(),
            kind,
            currency: "USD".into(),
            credit_limit: None,
            apr_bps: None,
            minimum_payment: None,
            statement_day: None,
            note: None,
        }
    }

    #[test]
    fn a_card_balance_typed_as_printed_becomes_a_debt() {
        // THE WHOLE POINT. A person types 2431.07 because that is what they are looking at. Stored
        // unconverted it would be $2,431 of net worth in the wrong direction — a $4,862 error on one
        // account, and it would look entirely plausible.
        let b = from_printed("card", "2026-06-30", usd(243_107), Kind::Credit);
        assert_eq!(b.balance.minor, -243_107);
    }

    #[test]
    fn a_chequing_balance_typed_as_printed_is_left_alone() {
        assert_eq!(from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking).balance.minor, 120_000);
    }

    #[test]
    fn an_overpaid_card_prints_negative_and_becomes_money_you_have() {
        // The rule holds in both directions rather than being a special case for the common one.
        assert_eq!(from_printed("card", "2026-06-30", usd(-5_000), Kind::Credit).balance.minor, 5_000);
    }

    #[test]
    fn the_latest_observation_is_the_one_used() {
        // position rolls forward from it, so the nearer the observation the less there is to get
        // wrong on top of it.
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-04-30", usd(300_000), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-05-31", usd(280_000), Kind::Credit));
        assert_eq!(latest_for(&bs, "card").unwrap().as_of, "2026-06-30");
        assert_eq!(bs.len(), 3, "earlier observations are kept, not overwritten");
    }

    #[test]
    fn the_same_account_on_the_same_day_is_a_correction_not_a_second_observation() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-06-30", usd(999_999), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        assert_eq!(bs.len(), 1);
        assert_eq!(bs[0].balance.minor, -243_107);
    }

    #[test]
    fn latest_each_gives_position_exactly_one_row_per_account() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-04-30", usd(300_000), Kind::Credit));
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking));
        let latest = latest_each(&bs);
        assert_eq!(latest.len(), 2);
        assert_eq!(latest.iter().find(|b| b.account == "card").unwrap().balance.minor, -243_107);
    }

    #[test]
    fn an_account_with_no_balance_is_named_rather_than_shown_as_zero() {
        let accounts = [acct("card", Kind::Credit), acct("checking", Kind::Checking)];
        let bs = vec![from_printed("card", "2026-06-30", usd(243_107), Kind::Credit)];
        assert_eq!(without_balance(&accounts, &bs), ["checking"]);
        assert!(without_balance(&accounts, &[]).len() == 2);
    }

    #[test]
    fn a_round_trip_keeps_the_sign_and_the_currency() {
        let mut bs = Vec::new();
        record(&mut bs, from_printed("card", "2026-06-30", usd(243_107), Kind::Credit));
        record(&mut bs, from_printed("checking", "2026-06-30", usd(120_000), Kind::Checking));
        let back = from_json(&to_json(&bs));
        assert_eq!(back, bs);
        assert_eq!(back[0].balance.minor, -243_107);
    }

    #[test]
    fn the_wire_shape_says_the_number_is_signed() {
        // A reader that took this for a printed figure would negate every card balance back to
        // wrong, so the key says which convention it is in.
        let bs = vec![from_printed("card", "2026-06-30", usd(243_107), Kind::Credit)];
        let v = to_json(&bs);
        assert!(v[0].get("signedMinor").is_some());
        assert!(v[0].get("printed").is_none());
        assert_eq!(v[0]["signedMinor"], -243_107);
    }

    #[test]
    fn rubbish_in_the_store_is_dropped_rather_than_defaulted() {
        let v = serde_json::json!([
            { "account": "ok", "asOf": "2026-06-30", "signedMinor": -1, "currency": "USD" },
            { "account": "no-date", "signedMinor": -1 },
            { "asOf": "2026-06-30", "signedMinor": -1 },
        ]);
        let back = from_json(&v);
        assert_eq!(back.len(), 1);
        assert_eq!(back[0].account, "ok");
    }
}

//! Recurring detection — find the standing charges nobody is looking at.
//!
//! The highest-value capability in the finance set, and the reason is unglamorous: a forgotten
//! subscription is found by NOBODY until something looks for it. It does not appear on a budget, it
//! does not feel like a decision, and it renews on a schedule designed to be unremarkable.
//!
//! The output that matters is the ANNUALISED cost. "$14.99" prompts nothing; "$179.88 a year" prompts
//! a cancellation. Same charge, and only one of those gets acted on.
//!
//! # Confidence, not a verdict
//!
//! A monthly bill whose amount moves — a utility, anything usage-based — is still recurring, and a
//! detector demanding an identical amount would miss exactly the charges worth finding. So regularity
//! and amount stability are scored separately and both are reported. Nothing here decides for the
//! reader; it hands them two numbers and the annual figure.
use crate::money::{money, scale, sum, Currency, Money, Rounding};
use crate::txn::{days_between, merchant_key_default, Txn};

/// How often something recurs. `Irregular` is a real answer, not a failure to classify.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cadence {
    Weekly,
    Biweekly,
    Monthly,
    Quarterly,
    Annual,
    Irregular,
}

impl Cadence {
    /// How many times a year this lands. `Irregular` has no answer and says so rather than guessing.
    pub fn per_year(self) -> Option<i64> {
        match self {
            Cadence::Weekly => Some(52),
            Cadence::Biweekly => Some(26),
            Cadence::Monthly => Some(12),
            Cadence::Quarterly => Some(4),
            Cadence::Annual => Some(1),
            Cadence::Irregular => None,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Cadence::Weekly => "weekly",
            Cadence::Biweekly => "biweekly",
            Cadence::Monthly => "monthly",
            Cadence::Quarterly => "quarterly",
            Cadence::Annual => "annual",
            Cadence::Irregular => "irregular",
        }
    }
}

/// The interval in days each cadence implies, and how far a gap may stray and still count.
const CADENCE_DAYS: [(Cadence, i64, i64); 5] = [
    (Cadence::Weekly, 7, 2),
    (Cadence::Biweekly, 14, 3),
    (Cadence::Monthly, 30, 5),
    (Cadence::Quarterly, 91, 12),
    (Cadence::Annual, 365, 35),
];

#[derive(Debug, Clone, PartialEq)]
pub struct Recurring {
    /// The merchant key the occurrences share — stable across the noise statements add.
    pub key: String,
    /// The most recent description, so a human recognises what it is.
    pub label: String,
    pub account: String,
    pub cadence: Cadence,
    /// Typical amount — the MEDIAN, not the mean: one annual true-up must not move the figure.
    pub typical: Money,
    /// What it costs over a year at this cadence. The number that prompts action.
    pub annualised: Money,
    pub occurrences: usize,
    pub first_seen: String,
    pub last_seen: String,
    /// 0-1, to two decimals. How evenly spaced the occurrences are; 1 is metronomic.
    pub regularity: f64,
    /// 0-1, to two decimals. How stable the amount is; 1 is identical every time.
    pub amount_stability: f64,
    /// Nothing charged for noticeably longer than the cadence predicts. Either it was cancelled or
    /// it is about to hit, and those want different responses — so it is surfaced, not filtered.
    pub lapsed: bool,
}

pub struct DetectOptions<'a> {
    /// Fewest occurrences before something counts as recurring. TWO is deliberate — an annual charge
    /// cannot show three inside a year of statements, and demanding three would hide precisely the
    /// once-a-year renewals that are easiest to forget and most expensive to keep.
    pub min_occurrences: usize,
    /// Ignore inbound money; income has its own capability and its own questions.
    pub outflows_only: bool,
    /// `YYYY-MM-DD` — what "now" is, for the lapsed check. Passed IN, never read from a clock, so
    /// the same data gives the same answer on a re-run and a test is not a moving target.
    pub as_of: &'a str,
}

impl<'a> DetectOptions<'a> {
    /// The defaults the TypeScript kit applies when the caller supplies only `asOf`.
    pub fn new(as_of: &'a str) -> Self {
        DetectOptions { min_occurrences: 2, outflows_only: true, as_of }
    }
}

/// The median, matching the TypeScript exactly — including that an even count ROUNDS THE MIDPOINT.
///
/// `Math.round` is half-up toward positive infinity. Every caller here passes non-negative values
/// (absolute amounts, and day gaps), where half-up and half-away-from-zero agree, so the difference
/// cannot surface — but it is written the way it is so that stays true if a negative ever arrives.
fn median(xs: &[i64]) -> i64 {
    if xs.is_empty() {
        return 0;
    }
    let mut s = xs.to_vec();
    s.sort_unstable();
    let m = s.len() / 2;
    if s.len() % 2 == 1 {
        s[m]
    } else {
        let total = s[m - 1] + s[m];
        // half-up toward +inf: -3/2 is -1.5, which rounds to -1, not -2.
        if total >= 0 { (total + 1).div_euclid(2) } else { -((-total).div_euclid(2)) }
    }
}

fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

/// The cadence whose expected interval the observed gaps sit closest to.
///
/// Regularity measures how tightly the gaps CLUSTER on the expected interval, not merely that the
/// median landed near it: twelve charges at 30 days and twelve alternating 5/55 share a median, and
/// only one of them is a subscription. The alternating case scores 0 and is still reported — the
/// score is the finding, not a filter.
pub fn classify(gaps: &[i64]) -> (Cadence, f64) {
    if gaps.is_empty() {
        return (Cadence::Irregular, 0.0);
    }
    let typical = median(gaps);
    let Some(&(cadence, days, _)) = CADENCE_DAYS.iter().find(|(_, days, tol)| (typical - days).abs() <= *tol) else {
        return (Cadence::Irregular, 0.0);
    };
    let drift = gaps.iter().map(|g| (g - days).abs() as f64).sum::<f64>() / gaps.len() as f64;
    (cadence, (1.0 - drift / days as f64).max(0.0))
}

/// Group by merchant AND account, then judge each group's rhythm.
///
/// The group identity is a `(account, key)` PAIR rather than a joined string. The TypeScript joins
/// them with a NUL byte precisely because a merchant key contains spaces — "rent landlord" — and any
/// printable separator would be ambiguous. A tuple has no separator to get wrong, so the hazard the
/// NUL exists to dodge does not reach this port at all.
///
/// Keyed on the ACCOUNT too: one subscription billed to two cards is two standing charges, and
/// merging them would halve the count while doubling the apparent amount.
pub fn detect_recurring(txns: &[Txn], opts: &DetectOptions) -> Vec<Recurring> {
    // Insertion-ordered, because the output sort is STABLE and ties therefore fall back to the order
    // groups were first seen. A HashMap would make two equal-cost accounts swap between runs.
    let mut groups: Vec<((String, String), Vec<&Txn>)> = Vec::new();
    for t in txns {
        if opts.outflows_only && t.amount.minor >= 0 {
            continue;
        }
        let key = merchant_key_default(&t.description);
        if key.is_empty() {
            continue;
        }
        let id = (t.account.clone(), key);
        match groups.iter_mut().find(|(gid, _)| *gid == id) {
            Some((_, bucket)) => bucket.push(t),
            None => groups.push((id, vec![t])),
        }
    }

    let mut out: Vec<Recurring> = Vec::new();
    for (id, rows) in groups {
        if rows.len() < opts.min_occurrences {
            continue;
        }
        let mut sorted = rows;
        sorted.sort_by(|a, b| a.date.cmp(&b.date));
        let gaps: Vec<i64> = sorted.windows(2).map(|w| days_between(&w[0].date, &w[1].date)).collect();
        let (cadence, regularity) = classify(&gaps);
        if cadence == Cadence::Irregular {
            continue;
        }

        let amounts: Vec<i64> = sorted.iter().map(|t| t.amount.minor.abs()).collect();
        let typical_minor = median(&amounts);
        let spread = amounts.iter().map(|v| (v - typical_minor).abs() as f64).sum::<f64>() / amounts.len() as f64;
        // A group whose typical amount is zero is stable by definition — there is nothing to vary.
        let amount_stability = if typical_minor == 0 { 1.0 } else { (1.0 - spread / typical_minor as f64).max(0.0) };

        let last = sorted[sorted.len() - 1];
        let typical = money(typical_minor, last.amount.currency);
        let (_, expected, tol) = CADENCE_DAYS.iter().find(|(c, _, _)| *c == cadence).copied().expect("a classified cadence is in the table");
        let per_year = cadence.per_year().expect("a classified cadence is never irregular");

        out.push(Recurring {
            key: id.1,
            label: last.description.clone(),
            account: last.account.clone(),
            cadence,
            typical,
            annualised: scale(typical, per_year as f64, Rounding::HalfUp),
            occurrences: sorted.len(),
            first_seen: sorted[0].date.clone(),
            last_seen: last.date.clone(),
            regularity: round2(regularity),
            amount_stability: round2(amount_stability),
            lapsed: days_between(&last.date, opts.as_of) > expected + tol,
        });
    }
    // Biggest annual cost first — the order a reader wants, because it is the order to act in.
    out.sort_by_key(|r| std::cmp::Reverse(r.annualised.minor));
    out
}

/// What every LIVE recurring charge costs in a year, together. Usually the number that lands.
///
/// Lapsed charges are excluded because the figure is meant to be actionable: adding back a
/// subscription that already stopped would overstate what cancelling everything could recover.
pub fn total_annualised(rs: &[Recurring], currency: Currency) -> Result<Money, crate::money::CurrencyMismatch> {
    let live: Vec<Money> = rs.iter().filter(|r| !r.lapsed).map(|r| r.annualised).collect();
    sum(&live, currency)
}

