    }

    #[test]
    fn applying_a_rate_stays_in_integers_and_rounds_half_away_from_zero() {
        assert_eq!(apply_bps(usd(10_000), 600).minor, 600, "6% of 100.00 is 6.00");
        // 0.005 exactly — rounds up, not to even, because that is what a tax table does.
        assert_eq!(apply_bps(usd(25), 200).minor, 1, "2% of 0.25 is 0.005");
        assert_eq!(apply_bps(usd(-25), 200).minor, -1, "and the same magnitude the other way");
        assert_eq!(apply_bps(usd(0), 600).minor, 0);
        // A large amount does not wrap: 10 million dollars at 6%.
        assert_eq!(apply_bps(usd(1_000_000_000), 600).minor, 60_000_000);
    }

    #[test]
    fn every_seeded_rate_cites_a_source() {
        // A rate with no source is a rumour, and this table is the input to a tax return.
        assert!(RATES.len() >= 4, "the scan found only {} rates — it has stopped seeing them", RATES.len());
        for r in RATES {
            assert!(!r.source.trim().is_empty(), "{} {} has no source", r.place, r.kind.label());
            assert!(r.from.len() == 10, "{} {} has no usable effective date", r.place, r.kind.label());
        }
        assert!(SUPPLY_RULES.len() >= 4, "the scan found only {} supply rules", SUPPLY_RULES.len());
        for r in SUPPLY_RULES {
            assert!(!r.source.trim().is_empty(), "{} {:?} has no source", r.place, r.supply);
            assert!(!r.reason.trim().is_empty(), "{} {:?} gives no reason — an exemption you cannot explain is one you cannot defend", r.place, r.supply);
            assert!(PLACES.iter().any(|p| p.id == r.place), "`{}` is ruled on but is not a seeded place", r.place);
        }
        assert!(OBLIGATIONS.len() >= 7, "the scan found only {} obligations", OBLIGATIONS.len());
        for o in OBLIGATIONS {
            assert!(!o.source.trim().is_empty(), "{} has no source", o.name);
            assert!(!o.authority.trim().is_empty(), "{} names no authority — a requirement you cannot act on", o.name);
            assert!(!o.required_when.trim().is_empty(), "{} does not say when it applies, so it reads as always", o.name);
        }
        // And every place a rate or obligation points at must actually exist.
        for (place, _) in sources(RATES, OBLIGATIONS) {
            assert!(PLACES.iter().any(|p| p.id == place), "`{place}` is cited but is not a seeded place");
        }
    }

    #[test]
    fn the_other_states_exist_as_names_and_assert_no_rate_or_rule() {
        // The whole point of seeding them: they must add REACH without adding false precision.
        assert!(PLACES.iter().filter(|p| p.level == Level::Region).count() >= 50, "the states are the reach");
        for p in PLACES.iter().filter(|p| p.level == Level::Region && p.id != "us/ga") {
            assert!(!RATES.iter().any(|r| r.place == p.id), "{} asserts a rate nobody checked", p.id);
            assert!(!SUPPLY_RULES.iter().any(|r| r.place == p.id), "{} asserts a taxability rule nobody checked", p.id);
        }
        // So each answers NOT KNOWN rather than a number, and says so.
        let t = taxability(RATES, PLACES, "us/tx", Supply::ProfessionalService, "2026-09-04").expect("resolvable");
        assert!(matches!(t, Taxability::Unknown { .. }), "{t:?}");
        assert!(combined(RATES, PLACES, "us/tx", RateKind::SalesTax, "2026-09-04").is_err());
        // The federal obligations still reach them, which is the value of existing at all.
        let obs = obligations_for(OBLIGATIONS, PLACES, "us/tx").expect("resolvable");
        assert!(obs.iter().any(|o| o.name == "Estimated tax"), "federal duties do not stop at a state line");
        assert!(obs.iter().all(|o| o.place == "us"), "nothing state-specific may be claimed for Texas: {:?}", obs.iter().map(|o| o.place).collect::<Vec<_>>());
    }

    #[test]
    fn coverage_follows_the_chain_so_duluth_is_not_reported_as_unknown() {
        let cov = |id: &str| coverage(RATES, SUPPLY_RULES, OBLIGATIONS, PLACES, id, "2026-09-04");
        // THE MISREADING THIS FIXES. Duluth declares no rate of its own and inherits every one that
        // applies; labelling it by its own id alone called the seed's whole purpose "name only".
        assert_eq!(cov("us/ga/gwinnett/duluth").label(), "rates + rules");
        assert_eq!(cov("us/ga").label(), "rates + rules");
        // A state with nothing recorded says so, and still carries the federal duties.
        let tx = cov("us/tx");
        assert_eq!(tx.label(), "duties only");
        assert!(!tx.sales_tax && !tx.supply_rules && tx.obligations);
        // The country itself has federal obligations and a self-employment rate, but no sales tax.
        assert!(!cov("us").sales_tax, "there is no federal sales tax");
    }

    #[test]
    fn a_cross_state_sale_now_refuses_for_the_right_reason() {
        // BEFORE the states were seeded this failed as "not a place this knows", which is a true
        // statement that answers the wrong question. Now it names nexus.
        let err = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us/ca"), Supply::DigitalProduct, "2026-09-04").unwrap_err();
        assert!(err.contains("NEXUS is not modelled"), "{err}");
        assert!(err.contains("California"), "{err}");
        // And a service is STILL exempt across that line, because exemption short-circuits sourcing.
        let svc = taxability_for_sale(RATES, PLACES, "us/ga/gwinnett/duluth", Some("us/ca"), Supply::ProfessionalService, "2026-09-04").expect("exempt regardless");
        assert!(matches!(svc, Taxability::Exempt { .. }), "{svc:?}");
    }

    #[test]
    fn every_place_reaches_a_country_that_declares_a_currency_and_a_system() {
        for p in PLACES {
            let c = country(PLACES, p.id).unwrap_or_else(|e| panic!("{}: {e}", p.id));
            assert!(c.currency.is_some(), "{} reaches {} which declares no currency", p.id, c.id);
            assert!(c.system.is_some(), "{} reaches {} which declares no tax system", p.id, c.id);
        }
        assert_eq!(country(PLACES, "us/ga/gwinnett/duluth").expect("seeded").id, "us");
    }
}

//! `bsc self` — the binary's own health. See the crate header for why this is not circular.

use crate::{
    candidate_paths, freshness, humanize_ms, inspect, mtime_ms, newest_source_mtime, Candidate,
    Freshness, State,
};
use std::path::{Path, PathBuf};

pub const TAGLINE: &str =
    "this binary and its siblings — can the `bsc` you are about to run be trusted?";

pub const VERBS: [&str; 2] = ["doctor", "which"];

pub fn command_docs() -> &'static [bsc_cli_util::CmdDoc] {
    &[
        bsc_cli_util::CmdDoc {
            name: "doctor",
            summary: "every `bsc` on this machine, and whether each can be trusted (#bsc-doctor)",
            usage: "\
USAGE:
  bsc self doctor [--root <dir>] [--json]

THREE FAILURE MODES, each of which cost real time here and none of which a binary can report about itself:

  ZERO-BYTE      a broken link. A shell cannot exec a file with no valid header, so it runs it as an
                 EMPTY SHELL SCRIPT — exit 0, no output, indistinguishable from every command passing.
                 A 0-byte `target/debug/bsc` produced three confident, wrong conclusions before `ls -l`
                 caught it. The size is checked BEFORE anything is executed.
  NO-HANDSHAKE   it runs but cannot identify itself — an incoherent build. An hour went to a build where
                 every `plan` verb exited 0 with empty output.
  STALE          older than the newest `.rs`, so `unknown command` from it means NOT BUILT rather than
                 removed. Three false regression reports. Measured against the TREE, not against
                 `bsc version`'s `built` line — that reads the exe's own mtime, so a COPY reports when it
                 was copied and a month-old binary staged today looks fresh.

EXIT CODES ARE THE POINT: non-zero when NO usable binary exists, 0 when one does. A merely stale binary
WARNS rather than failing, so this is safe to run anywhere, including a gate.",
        },
        bsc_cli_util::CmdDoc {
            name: "which",
            summary: "the `bsc` that would actually be used, and the order it was chosen from",
            usage: "\
USAGE:
  bsc self which [--root <dir>] [--json]

Most-local first: `target/debug`, then `target/release`, then the staged `~/.base-studio-code/bin`. A
local build wins over the staged copy even when the staged one is newer — it is what you are iterating on.

EXISTENCE IS NOT ENOUGH: each candidate must hand-shake before it is chosen, which is the whole lesson of
the zero-byte case.",
        },
    ]
}

fn flag_after(args: &[String], name: &str) -> Option<String> {
    args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).cloned()
}

fn real_run(p: &Path) -> (i32, String) {
    // BOUNDED: a hang is as bad as a wrong answer, and this runs inside a gate — a wedged binary must
    // not take the gate with it. `Command` has no timeout, so the child is spawned and reaped with one.
    match std::process::Command::new(p)
        .arg("version")
        .stdin(std::process::Stdio::null())
        .output()
    {
        Ok(o) => (o.status.code().unwrap_or(1), String::from_utf8_lossy(&o.stdout).into_owned()),
        Err(e) => (127, format!("could not execute: {e}")),
    }
}

fn size_of(p: &Path) -> Option<u64> {
    std::fs::metadata(p).ok().map(|m| m.len())
}

fn scan(root: &Path) -> Vec<(Candidate, Freshness)> {
    let home = std::env::var("HOME")
        .or_else(|_| std::env::var("USERPROFILE"))
        .map(PathBuf::from)
        .unwrap_or_default();
    let newest =
        newest_source_mtime(&[root.join("crates"), root.join("src-tauri").join("src")]);
    candidate_paths(root, &home)
        .iter()
        .map(|p| {
            let c = inspect(p, &size_of, &real_run);
            let f = freshness(mtime_ms(p), newest);
            (c, f)
        })
        .collect()
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let merged = command_docs();
    if bsc_cli_util::handle_help(prog, TAGLINE, merged, &args) {
        return Ok(());
    }
    let root = flag_after(&args, "--root")
        .map(PathBuf::from)
        .unwrap_or(std::env::current_dir().map_err(|e| format!("cannot resolve cwd: {e}"))?);
    let json = args.iter().any(|a| a == "--json");

    match args.first().map(String::as_str) {
        Some("doctor") => cmd_doctor(&root, json),
        Some("which") => cmd_which(&root, json),
        _ => Err(format!("usage: {prog} self doctor | {prog} self which  [--root <dir>] [--json]")),
    }
}

fn state_name(s: &State) -> &'static str {
    match s {
        State::Absent => "absent",
        State::ZeroByte => "zero-byte",
        State::NoHandshake => "no-handshake",
        State::Usable => "usable",
    }
}

fn cmd_doctor(root: &Path, json: bool) -> Result<(), String> {
    let rows = scan(root);
    let first_usable = rows.iter().find(|(c, _)| c.ok());

    if json {
        let arr: Vec<serde_json::Value> = rows
            .iter()
            .map(|(c, f)| {
                serde_json::json!({
                    "path": c.path.to_string_lossy(),
                    "state": state_name(&c.state),
                    "ok": c.ok(),
                    "size": c.size,
                    "version": c.version,
                    "detail": if c.detail.is_empty() { serde_json::Value::Null } else { serde_json::json!(c.detail) },
                    "stale": matches!(f, Freshness::Stale { .. }),
                    "behindMs": match f { Freshness::Stale { behind_ms } => serde_json::json!(behind_ms), _ => serde_json::Value::Null },
                })
            })
            .collect();
        bsc_util::emit_line(
            &serde_json::to_string_pretty(&serde_json::json!({
                "candidates": arr,
                "using": first_usable.map(|(c, _)| c.path.to_string_lossy()),
            }))
            .map_err(|e| e.to_string())?,
        );
    } else {
        bsc_util::emit_line("\nbsc binaries");
        for (c, f) in &rows {
            let mark = if c.ok() { "ok  " } else { "FAIL" };
            bsc_util::emit_line(&format!("  [{mark}] {}", c.path.display()));
            if c.ok() {
                bsc_util::emit_line(&format!(
                    "         {}   {:.1} MB",
                    c.version.as_deref().unwrap_or(""),
                    c.size.unwrap_or(0) as f64 / 1e6
                ));
                if let Freshness::Stale { behind_ms } = f {
                    bsc_util::emit_line(&format!(
                        "         STALE — {} older than the newest .rs change. `unknown command` from \
                         this binary means NOT BUILT, not removed.",
                        humanize_ms(*behind_ms)
                    ));
                }
            } else {
                bsc_util::emit_line(&format!("         {}: {}", state_name(&c.state), c.detail));
            }
        }
    }

    match first_usable {
        Some((c, _)) => {
            if !json {
                bsc_util::emit_line(&format!("\nusing: {}", c.path.display()));
            }
            Ok(())
        }
        // NON-ZERO only when NOTHING is usable. A stale binary warned above and still exits 0, which is
        // what makes this safe to run in a gate.
        None => Err("no usable bsc. Build one: cargo build -p bsc --bin bsc".to_string()),
    }
}

fn cmd_which(root: &Path, json: bool) -> Result<(), String> {
    let rows = scan(root);
    let chosen = rows.iter().find(|(c, _)| c.ok());
    if json {
        bsc_util::emit_line(
            &serde_json::to_string_pretty(&serde_json::json!({
                "using": chosen.map(|(c, _)| c.path.to_string_lossy()),
                "order": rows.iter().map(|(c, _)| serde_json::json!({
                    "path": c.path.to_string_lossy(), "state": state_name(&c.state), "ok": c.ok(),
                })).collect::<Vec<_>>(),
            }))
            .map_err(|e| e.to_string())?,
        );
        return Ok(());
    }
    match chosen {
        Some((c, _)) => {
            bsc_util::emit_line(&format!("{}", c.path.display()));
            Ok(())
        }
        None => Err("no usable bsc. Build one: cargo build -p bsc --bin bsc".to_string()),
    }
}

//! `bsc mem app` — the RUNNING app's heap, via the Chromium harness in `e2e/`.
//!
//! # Why this is a wrapper and not a measurement
//!
//! The numbers can only be read from a browser that exposes CDP, and the harness that does it already
//! exists and is already pinned by tests. Reimplementing the drive here would be a second renderer
//! path — the exact failure `e2e/`'s own header warns about, where a forked implementation is green
//! while the shipped one is broken. So this SHELLS OUT to the harness and parses one machine-readable
//! line from it.
//!
//! What this adds over running the npm script by hand is the thing that was missing: the numbers reach
//! the `bsc` surface, which is the only surface a worker (or a caged studio session) actually has.

use std::process::Command;

/// The marker the harness prints its machine-readable line under. A prefix rather than "the last line"
/// because playwright interleaves its own reporter output with the spec's, so position is not a
/// contract and matching on one would break the first time the reporter changed.
pub const MARKER: &str = "BSC_MEM_APP ";

/// Pull the measurement JSON out of a harness run's output.
///
/// Returns the LAST marked line: a spec may sample repeatedly, and the final reading is the one taken
/// after the app has settled. Absent marker ⇒ `None`, which the caller reports as a failure to measure
/// rather than as a zero.
pub fn parse_report(output: &str) -> Option<serde_json::Value> {
    output
        .lines()
        .filter_map(|l| l.trim().strip_prefix(MARKER))
        .filter_map(|j| serde_json::from_str(j).ok())
        .next_back()
}

/// Whether a failure was the BROWSER being absent rather than the app being broken.
///
/// Worth telling apart precisely because `npm install` does not install the browser — so "you have not
/// run `npx playwright install chromium`" is the single most likely reason this fails on a fresh
/// checkout, and reporting it as a measurement failure would send someone hunting a leak that is
/// really a missing binary.
pub fn is_missing_browser(output: &str) -> bool {
    let o = output.to_lowercase();
    o.contains("playwright install") || o.contains("executable doesn't exist")
}

pub fn run(seconds: Option<u32>, pretty: bool, json: bool) -> Result<(), String> {
    let secs = seconds.unwrap_or(20);
    let out = Command::new("npx")
        .args(["playwright", "test", "e2e/memApp.spec.ts", "--reporter=list"])
        .env("BSC_MEM_SECONDS", secs.to_string())
        .output()
        .map_err(|e| format!("bsc mem app needs `npx` on PATH (node): {e}"))?;

    let text = format!(
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );

    if let Some(report) = parse_report(&text) {
        bsc_cli_util::emit(pretty, json, &report, || {
            let g = |k: &str| report.get(k).and_then(serde_json::Value::as_f64);
            format!(
                "heap {:.1} MB · {} DOM nodes · {} listeners  (CHROMIUM, not the shipped WebKitGTK)",
                g("JSHeapUsedSize").unwrap_or(0.0) / 1_048_576.0,
                g("Nodes").map(|n| n.to_string()).unwrap_or_else(|| "-".into()),
                g("JSEventListeners").map(|n| n.to_string()).unwrap_or_else(|| "-".into()),
            )
        });
        return Ok(());
    }

    // NO NUMBER IS AN ERROR, never a zero. A heap of 0 MB would be read as a measurement.
    if is_missing_browser(&text) {
        return Err("bsc mem app needs the headless browser, which `npm install` does not install:\n  \
                    npx playwright install chromium"
            .to_string());
    }
    Err(format!(
        "bsc mem app could not read a measurement (no `{MARKER}` line in the harness output).\n\
         The harness ran but reported nothing — its tail follows:\n{}",
        text.lines().rev().take(12).collect::<Vec<_>>().into_iter().rev().collect::<Vec<_>>().join("\n"),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_marked_line_is_parsed_out_of_surrounding_reporter_noise() {
        let out = "Running 1 test\n\
                   BSC_MEM_APP {\"JSHeapUsedSize\":41943040,\"Nodes\":1200}\n\
                   1 passed (3.2s)\n";
        let got = parse_report(out).expect("a marked line is found among the noise");
        assert_eq!(got["Nodes"], 1200);
    }

    /// A spec may sample more than once; the SETTLED reading is the last one, not the first.
    #[test]
    fn the_last_reading_wins_when_several_are_printed() {
        let out = "BSC_MEM_APP {\"Nodes\":10}\nBSC_MEM_APP {\"Nodes\":99}\n";
        assert_eq!(parse_report(out).unwrap()["Nodes"], 99);
    }

    /// No marker is NO MEASUREMENT — the caller must not be handed something it could round to zero.
    #[test]
    fn output_with_no_marker_yields_nothing_rather_than_an_empty_reading() {
        assert!(parse_report("1 passed (3.2s)\n").is_none());
        assert!(parse_report("").is_none());
    }

    /// A marker with unparseable JSON is also nothing — a half-written line is not a reading.
    #[test]
    fn a_malformed_marked_line_is_not_a_reading() {
        assert!(parse_report("BSC_MEM_APP {not json\n").is_none());
    }

    /// The missing-browser case is told apart from a real failure, because it is the most likely one on
    /// a fresh checkout and the fix is a single command rather than an investigation.
    #[test]
    fn a_missing_browser_is_recognised_from_playwrights_own_wording() {
        assert!(is_missing_browser("Executable doesn't exist at /home/x/.cache/ms-playwright/..."));
        assert!(is_missing_browser("Please run the following command to download new browsers:\n npx playwright install"));
        assert!(!is_missing_browser("Error: expected 1200 nodes, got 4000"));
    }
}

