            Node::Sphere { r } => p.length() - r,
            Node::Cylinder { r, h } => {
                let d_xy = (p.x * p.x + p.y * p.y).sqrt() - r;
                let d_z = p.z.abs() - h * 0.5;
                let outside = (d_xy.max(0.0).powi(2) + d_z.max(0.0).powi(2)).sqrt();
                d_xy.max(d_z).min(0.0) + outside
